pub fn escape(s: &str) -> String {
    s.replace('&', "&amp;")
        .replace('<', "&lt;")
        .replace('>', "&gt;")
        .replace('"', "&quot;")
        .replace('\'', "&#39;")
}

// Markdown otherwise consumes TeX row breaks and rewrites primes via smart
// punctuation. Protect explicit math before any roles or directives are parsed.
// The doubled delimiter backslashes are the book's Markdown authoring spelling;
// the HTML text passed to MathJax contains ordinary single-backslash delimiters.
fn protect_math(source: &str) -> String {
    let literal: Vec<_> = Parser::new(source)
        .into_offset_iter()
        .filter_map(|(event, range)| match event {
            Event::Start(
                Tag::CodeBlock(_) | Tag::HtmlBlock | Tag::Link { .. } | Tag::Image { .. },
            )
            | Event::Code(_)
            | Event::Html(_)
            | Event::InlineHtml(_) => Some(range),
            _ => None,
        })
        .collect();
    let mut output = String::new();
    let mut end = 0;
    for (start, _) in source.match_indices(r"\\") {
        if start < end
            || source[..start].ends_with('\\')
            || literal.iter().any(|range| range.contains(&start))
        {
            continue;
        }
        let (display, closing) = match source.as_bytes().get(start + 2) {
            Some(b'[') => (true, r"\\]"),
            Some(b'(') => (false, r"\\)"),
            _ => continue,
        };
        let body_start = start + 3;
        let Some(close) = source[body_start..].find(closing).map(|i| body_start + i) else {
            continue;
        };
        if literal.iter().any(|range| range.contains(&close)) {
            continue;
        }
        let body = &source[body_start..close];
        output.push_str(&source[end..start]);
        if display {
            let tex = escape(body).replace('\n', "&#10;");
            output.push_str(&format!(
                "\n\n<div class=\"math-display\">\\[{tex}\\]</div>\n\n"
            ));
        } else {
            // Inline HTML does not suppress Markdown parsing of its contents.
            // Entities keep every TeX punctuation character out of that parser.
            let tex: String = format!("\\({body}\\)")
                .chars()
                .map(|c| {
                    if c.is_alphanumeric() || c == ' ' {
                        c.to_string()
                    } else {
                        format!("&#{};", u32::from(c))
                    }
                })
                .collect();
            output.push_str(&format!("<span class=\"math-inline\">{tex}</span>"));
        }
        end = close + closing.len();
    }
    output.push_str(&source[end..]);
    output
}

#[derive(Debug)]
struct Role {
    range: Range<usize>,
    id: String,
    definition: bool,
    label: Option<&'static str>,
    lean: bool,
}

// Use Markdown's source ranges to recognize roles, leaving code examples, links,
// escaped text, and HTML blocks alone. The role body is a single-backtick code span.
fn roles(source: &str) -> Result<Vec<Role>> {
    let id_pattern = Regex::new(r"^[A-Za-z0-9][A-Za-z0-9_.-]*$")?;
    let mut found = vec![];
    let mut text_end = None;
    let mut excluded = 0;
    for (event, range) in Parser::new(source).into_offset_iter() {
        match event {
            Event::Start(
                Tag::CodeBlock(_) | Tag::Link { .. } | Tag::Image { .. } | Tag::HtmlBlock,
            ) => {
                excluded += 1;
                text_end = None;
            }
            Event::End(TagEnd::CodeBlock | TagEnd::Link | TagEnd::Image | TagEnd::HtmlBlock) => {
                excluded -= 1;
                text_end = None;
            }
            Event::Text(_) if excluded == 0 => text_end = Some(range),
            Event::Code(id) if excluded == 0 => {
                if let Some(previous) = text_end.take() {
                    let removed = "{obligation}";
                    if previous.end == range.start
                        && source[previous.clone()].ends_with(removed)
                        && !source[..range.start - removed.len()].ends_with('\\')
                        && source[range.clone()] == format!("`{id}`")
                    {
                        bail!("{{obligation}} has been removed; use a named definition, theorem, lemma, or example with :status: draft when formalization is pending");
                    }
                    for (prefix, definition, label, lean) in [
                        ("{anchor}", true, None, false),
                        ("{definition}", true, Some("definition"), false),
                        ("{anchor-ref}", false, None, false),
                        ("{lean.type}", false, None, true),
                    ] {
                        if previous.end != range.start
                            || !source[previous.clone()].ends_with(prefix)
                        {
                            continue;
                        }
                        let start = range.start - prefix.len();
                        if source[..start].ends_with('\\') {
                            continue;
                        }
                        // Double-backtick spans are literal demonstrations, not roles.
                        if source[range.clone()] != format!("`{id}`") {
                            continue;
                        }
                        ensure!(lean || id_pattern.is_match(&id), "invalid anchor ID `{id}`");
                        found.push(Role {
                            range: start..range.end,
                            id: id.into_string(),
                            definition,
                            label,
                            lean,
                        });
                        break;
                    }
                }
            }
            _ => text_end = None,
        }
    }
    Ok(found)
}

#[derive(Clone, Copy)]
enum MarkdownDirective {
    Definition,
    Example,
    Theorem,
    Lemma,
}

impl MarkdownDirective {
    fn parse(name: &str) -> Option<Self> {
        match name {
            "{definition}" => Some(Self::Definition),
            "{example}" => Some(Self::Example),
            "{theorem}" => Some(Self::Theorem),
            "{lemma}" => Some(Self::Lemma),
            _ => None,
        }
    }

    fn name(self) -> &'static str {
        match self {
            Self::Definition => "definition",
            Self::Example => "example",
            Self::Theorem => "theorem",
            Self::Lemma => "lemma",
        }
    }

    fn label(self) -> &'static str {
        match self {
            Self::Definition => "Definition",
            Self::Example => "Example",
            Self::Theorem => "Theorem",
            Self::Lemma => "Lemma",
        }
    }

    fn definition_label(self) -> &'static str {
        match self {
            Self::Definition => "definition",
            Self::Example => "anchor",
            Self::Theorem => "theorem",
            Self::Lemma => "lemma",
        }
    }
}

struct DirectiveBlock {
    range: Range<usize>,
    info: String,
    body: String,
}

fn directive_blocks(source: &str) -> Vec<DirectiveBlock> {
    let mut found = vec![];
    let mut block = None;
    for (event, range) in Parser::new(source).into_offset_iter() {
        match event {
            Event::Start(Tag::CodeBlock(CodeBlockKind::Fenced(info)))
                if [
                    "{heap}",
                    "{grammar}",
                    "{judgment}",
                    "{rule}",
                    "{definition}",
                    "{theorem}",
                    "{lemma}",
                    "{example}",
                    "{future-note}",
                    // Recognized only so the shared validator can reject it.
                    "{obligation}",
                    "{lean.type}",
                    "{lean.judgment}",
                    "{lean.rule}",
                ]
                .iter()
                .any(|name| info.starts_with(name)) =>
            {
                block = Some(DirectiveBlock {
                    range,
                    info: info.into_string(),
                    body: String::new(),
                });
            }
            Event::Text(text) => {
                if let Some(block) = &mut block {
                    block.body.push_str(&text);
                }
            }
            Event::End(TagEnd::CodeBlock) => {
                if let Some(mut block) = block.take() {
                    block.range.end = range.end;
                    found.push(block);
                }
            }
            _ => {}
        }
    }
    found
}

fn chapter_roles(source: &str) -> Result<Vec<Role>> {
    let protected = protect_math(source);
    let mut found = roles(&protected)?;
    for unit in units::parse(source, "chapter")? {
        found.push(Role {
            range: unit.range,
            id: unit.id,
            definition: true,
            label: None,
            lean: false,
        });
    }
    for block in directive_blocks(&protected) {
        if block
            .info
            .split_whitespace()
            .next()
            .is_some_and(|name| MarkdownDirective::parse(name).is_some() || name == "{future-note}")
        {
            // These bodies are Markdown; grammar, judgment, and rule bodies are TeX.
            ensure!(
                !directive_blocks(&block.body).iter().any(|nested| {
                    ["{definition}", "{example}", "{theorem}", "{lemma}", "{future-note}"]
                        .iter()
                        .any(|name| nested.info.starts_with(name))
                }),
                "definition, example, theorem, and lemma directives cannot be nested within one another"
            );
            found.extend(roles(&protect_math(&block.body))?);
        }
    }
    Ok(found)
}

fn render_unit(
    unit: &units::SpecUnit,
    path: &str,
    anchors: &BTreeMap<String, String>,
    lean_root: Option<&Path>,
    project_root: Option<&Path>,
) -> Result<String> {
    let label = unit.kind.label();
    let lower_label = label.to_ascii_lowercase();
    let role = Role {
        range: unit.range.clone(),
        id: unit.id.clone(),
        definition: true,
        label: None,
        lean: false,
    };
    let mut heading = render_role(&role, path, anchors, &lower_label)?;
    if unit.draft {
        heading.push_str(" <span class=\"block-label unit-status\" title=\"Formalization and correspondence review pending\">Draft</span>");
    }
    let (alternate, cited_source) = if !unit.lean.is_empty() {
        let root = lean_root.context("Lean directives require preprocessor.dada.lean-source")?;
        ("Lean", lean::selected_source(root, &unit.lean, unit.kind)?)
    } else if !unit.rust.is_empty() {
        let root = project_root.context("Rust citations require a configured project root")?;
        let mut cited = String::new();
        for target in unit.rust.iter().chain(&unit.tests) {
            let selected = crate::rust_source::select(root, target)?;
            cited.push_str(&format!(
                "<figcaption>{}</figcaption><pre><code class=\"language-rust\">{}</code></pre>",
                escape(target),
                escape(&selected.selected).replace('\n', "&#10;")
            ));
        }
        ("Rust", cited)
    } else {
        ("", String::new())
    };
    let header = if alternate.is_empty() {
        format!("<div class=\"lean-selector\"><div class=\"block-heading\">{heading}</div></div>")
    } else {
        selector_header(
            label,
            Some(&heading),
            &format!("unit-{}", unit.id),
            "rendered",
            alternate,
        )
    };
    let body = if unit.kind.is_math() {
        let tex = escape(unit.body.trim()).replace('\n', "&#10;");
        format!("<div class=\"lean-grammar\"><div class=\"math-display\">\\[{tex}\\]</div></div>")
    } else {
        let body = render(
            &unit.body,
            path,
            anchors,
            lean_root,
            project_root,
            &unit.id,
            &lower_label,
        )?;
        format!(
            "<div class=\"lean-markdown-body\">\n\n{}\n\n</div>",
            body.trim_matches('\n')
        )
    };
    let markdown_class = if unit.kind.is_math() {
        ""
    } else {
        " lean-markdown"
    };
    Ok(format!("\n<figure class=\"lean-declaration lean-group{markdown_class}\">{header}{body}<div class=\"lean-source\">{cited_source}</div></figure>\n\n"))
}

fn walk(chapters: &Value, f: &mut impl FnMut(&Value) -> Result<()>) -> Result<()> {
    if let Some(items) = chapters.as_array() {
        for item in items {
            if let Some(chapter) = item.get("Chapter") {
                f(chapter)?;
                walk(&chapter["sub_items"], f)?;
            }
        }
    }
    Ok(())
}

fn relative_html(from: &str, to: &str) -> Result<String> {
    // mdBook chapter paths are relative to the source directory.
    let parts = |s: &str| -> Result<Vec<String>> {
        Path::new(s)
            .components()
            .map(|c| match c {
                std::path::Component::Normal(p) => Ok(p.to_string_lossy().into_owned()),
                _ => bail!("chapter path must be relative and normalized: {s}"),
            })
            .collect()
    };
    let mut from = parts(from)?;
    from.pop();
    let mut to = parts(to)?;
    let file = to.last_mut().context("empty chapter path")?;
    *file = Path::new(file)
        .with_extension("html")
        .to_string_lossy()
        .into_owned();
    let common = from.iter().zip(&to).take_while(|(a, b)| a == b).count();
    let path = std::iter::repeat_n("..".to_owned(), from.len() - common)
        .chain(to[common..].iter().cloned())
        .collect::<Vec<_>>()
        .join("/");
    Ok(path
        .replace('%', "%25")
        .replace(' ', "%20")
        .replace('#', "%23")
        .replace('?', "%3F"))
}

fn render_role(
    role: &Role,
    path: &str,
    anchors: &BTreeMap<String, String>,
    definition_label: &str,
) -> Result<String> {
    ensure!(
        !role.lean,
        "lean.type has been replaced: use ```{{grammar}} path:Name with authored LaTeX in the body"
    );
    let target = anchors
        .get(&role.id)
        .with_context(|| format!("unknown anchor `{}`", role.id))?;
    let fragment = format!("claim-{}", role.id);
    let href = if target == path {
        format!("#{fragment}")
    } else {
        format!("{}#{fragment}", relative_html(path, target)?)
    };
    let id_attr = if role.definition {
        format!(" id=\"{fragment}\"")
    } else {
        String::new()
    };
    let label = if role.definition {
        role.label.unwrap_or(definition_label)
    } else {
        "ref"
    };
    Ok(format!(
        "<a{id_attr} class=\"spec-shield\" href=\"{}\" aria-label=\"{label}: {}\"><span class=\"spec-shield-label\">{label}</span><span class=\"spec-shield-name\">{}</span></a>",
        escape(&href), escape(&role.id), escape(&role.id)
    ))
}

// Only a sequence of declaration roles at the very start belongs in the header.
// Roles later in prose, inside literals, or inside nested directives stay put.
fn markdown_heading<'a>(
    source: &'a str,
    path: &str,
    anchors: &BTreeMap<String, String>,
    definition_label: &str,
) -> Result<(String, &'a str)> {
    let protected = protect_math(source);
    let mut heading = Vec::new();
    let mut end = 0;
    for role in roles(&protected)? {
        if !protected[end..role.range.start].trim().is_empty() || !role.definition {
            break;
        }
        heading.push(render_role(&role, path, anchors, definition_label)?);
        // A promoted role is preceded only by whitespace and other roles, so
        // math protection has not changed its source offsets.
        end = role.range.end;
    }
    Ok((heading.join(" "), &source[end..]))
}

/// Shared header for every rendered/source pair. The heading is generated HTML;
/// labels, group names, and radio values are escaped here.
pub(crate) fn selector_header(
    label: &str,
    heading: Option<&str>,
    group: &str,
    rendered_value: &str,
    alternate: &str,
) -> String {
    let label = escape(label);
    let fallback = format!("<span class=\"block-label\">{label}</span>");
    let heading = heading.unwrap_or(&fallback);
    let group = escape(group);
    let rendered_value = escape(rendered_value);
    let alternate_value = escape(&alternate.to_ascii_lowercase());
    let alternate = escape(alternate);
    format!("<div class=\"lean-selector\" role=\"group\" aria-label=\"{label} view\"><div class=\"block-heading\">{heading}</div><div class=\"view-options\"><label><input type=\"radio\" name=\"{group}\" value=\"{rendered_value}\" checked> Rendered</label><label><input type=\"radio\" name=\"{group}\" value=\"{alternate_value}\"> {alternate}</label></div></div>")
}

fn render(
    source: &str,
    path: &str,
    anchors: &BTreeMap<String, String>,
    lean_root: Option<&Path>,
    project_root: Option<&Path>,
    scope: &str,
    definition_label: &str,
) -> Result<String> {
    let protected = protect_math(source);
    let source = protected.as_str();
    let structured_units = units::parse(source, path)?;
    let mut edits = vec![];
    for role in roles(source)? {
        let rendered = render_role(&role, path, anchors, definition_label)?;
        edits.push((role.range, rendered));
    }
    for (event, range) in Parser::new(source).into_offset_iter() {
        if matches!(event, Event::Start(Tag::Paragraph)) {
            ensure!(
                !source[range.clone()].starts_with("{example} "),
                "the paragraph {{example}} marker has been replaced: use a fenced ```{{example}} path:anchor with a Markdown body and a Lean test, or label an unfinished scenario as informational"
            );
            if source[range.clone()].starts_with("{informational} ") {
                edits.push((
                    range.start..range.start + "{informational}".len(),
                    "<span class=\"informational-label\">Informational</span>".to_owned(),
                ));
            }
        }
    }

    for block in directive_blocks(source) {
        if let Some(unit) = structured_units
            .iter()
            .find(|unit| unit.range.start == block.range.start)
        {
            for dependency in &unit.uses {
                ensure!(
                    anchors.contains_key(dependency),
                    "unknown unit dependency `{dependency}`"
                );
            }
            edits.push((
                block.range,
                render_unit(unit, path, anchors, lean_root, project_root)?,
            ));
            continue;
        }
        let start = block.range.start;
        let kind = block.info;
        let facts = block.body;
        let (directive, argument) = kind.split_once(char::is_whitespace).unwrap_or((&kind, ""));
        ensure!(
            ![
                "{heap}",
                "{grammar}",
                "{rule}",
                "{judgment}",
                "{definition}",
                "{theorem}",
                "{lemma}",
                "{example}",
                "{future-note}"
            ]
            .iter()
            .any(|name| directive.starts_with(name) && directive != *name),
            "separate the directive name and citation with whitespace"
        );
        ensure!(!matches!(directive, "{lean.type}" | "{lean.judgment}" | "{lean.rule}"),
                        "{directive} has been replaced: use ```{{grammar}} path:Name, ```{{judgment}} path:Name, or ```{{rule}} path:Name.case with authored LaTeX in the body");
        let id = format!("{scope}-{start}");
        if let Some(markdown) = MarkdownDirective::parse(directive) {
            let name = markdown.name();
            let label = markdown.label();
            let citations = argument.split_whitespace().count();
            if matches!(markdown, MarkdownDirective::Definition) {
                ensure!(
                    citations > 0,
                    "definition requires at least one opening-line citation"
                );
            } else {
                ensure!(
                    citations == 1,
                    "{name} requires exactly one opening-line citation"
                );
            }
            ensure!(!facts.trim().is_empty(), "{name} requires a Markdown body");
            let root =
                lean_root.context("Lean directives require preprocessor.dada.lean-source")?;
            let lean_source = match markdown {
                MarkdownDirective::Definition => lean::definition_source(root, argument)?,
                MarkdownDirective::Example => lean::example_source(root, argument.trim())?,
                MarkdownDirective::Theorem | MarkdownDirective::Lemma => {
                    lean::theorem_source(root, argument.trim())?
                }
            };
            let heading_label = if matches!(markdown, MarkdownDirective::Example) {
                "example"
            } else {
                markdown.definition_label()
            };
            let (heading, body) = markdown_heading(&facts, path, anchors, heading_label)?;
            ensure!(
                !body.trim().is_empty(),
                "{name} requires a Markdown body after its heading anchors"
            );
            let body = render(
                body,
                path,
                anchors,
                lean_root,
                project_root,
                &id,
                markdown.definition_label(),
            )?;
            let selector = selector_header(
                label,
                (!heading.is_empty()).then_some(heading.as_str()),
                &format!("{name}-{id}"),
                "rendered",
                "Lean",
            );
            // Blank lines terminate raw HTML blocks so mdBook renders the body
            // as Markdown, including its explicit math delimiters and proof prose.
            edits.push((block.range, format!(
                "\n<figure class=\"lean-declaration lean-group lean-markdown lean-{name}\">{selector}<div class=\"lean-markdown-body\">\n\n{}\n\n</div><div class=\"lean-source\">{lean_source}</div></figure>\n\n",
                body.trim_matches('\n')
            )));
            continue;
        }
        let view = match directive {
            "{grammar}" => Some(lean::View::Grammar),
            "{judgment}" => Some(lean::View::Judgment),
            "{rule}" => Some(lean::View::Rule),
            _ => None,
        };
        if let Some(view) = view {
            let root =
                lean_root.context("Lean directives require preprocessor.dada.lean-source")?;
            edits.push((
                block.range,
                format!(
                    "\n{}\n",
                    lean::render_authored(root, argument.trim(), &facts, view, &id)?
                ),
            ));
            continue;
        }
        ensure!(
            argument.trim().is_empty(),
            "{directive} does not accept opening-line arguments"
        );
        let graph = graph::render(&facts)?;
        let selector = selector_header("Diagram", None, &format!("heap-{id}"), "rendered", "Facts");
        let source = escape(&facts).replace('\n', "&#10;");
        edits.push((block.range, format!("\n<figure class=\"heap-figure\">{selector}{graph}<pre class=\"heap-facts\"><code>{source}</code></pre></figure>\n")));
    }
    edits.sort_by_key(|(range, _)| range.start);
    let mut result = String::new();
    let mut end = 0;
    for (range, replacement) in edits {
        ensure!(range.start >= end, "overlapping markup");
        result.push_str(&source[end..range.start]);
        result.push_str(&replacement);
        end = range.end;
    }
    result.push_str(&source[end..]);
    Ok(result)
}

pub fn process(book: &mut Value) -> Result<()> {
    process_with_lean(book, None)
}

pub fn process_with_lean(book: &mut Value, lean_root: Option<&Path>) -> Result<()> {
    process_with_roots(book, lean_root, lean_root.and_then(Path::parent))
}

/// Production mdBook boundary. Raw source checks precede rendering so already
/// expanded includes cannot bypass structured-unit restrictions.
pub fn process_configured(context: &Value, book: &mut Value) -> Result<()> {
    let root = Path::new(
        context["root"]
            .as_str()
            .context("mdBook context has no root")?,
    )
    .canonicalize()
    .context("resolving mdBook root")?;
    let configuration = configuration::SourceConfiguration::load(&root)?;
    configuration.check_context(context)?;
    configuration.validate_chapters(&root, book)?;
    if root.join("spec.json").exists() {
        inventory::Inventory::load(&root)?;
    }
    let lean_root = configuration.lean_root(&root)?;
    process_with_roots(book, Some(&lean_root), Some(&root))
}

fn process_with_roots(
    book: &mut Value,
    lean_root: Option<&Path>,
    project_root: Option<&Path>,
) -> Result<()> {
    let key = if book.get("items").is_some_and(Value::is_array) {
        "items"
    } else if book.get("sections").is_some_and(Value::is_array) {
        "sections"
    } else {
        bail!("unsupported mdBook input: expected an items or sections array");
    };
    let mut anchors = BTreeMap::new();
    walk(&book[key], &mut |chapter| {
        let source = chapter["content"]
            .as_str()
            .context("chapter has no content")?;
        let path = chapter["path"].as_str().context("chapter has no path")?;
        lint::check_latex(source, path)?;
        for role in chapter_roles(source).with_context(|| path.to_owned())? {
            if role.definition {
                if let Some(previous) = anchors.insert(role.id.clone(), path.to_owned()) {
                    bail!("duplicate anchor `{}` in {previous} and {path}", role.id);
                }
            }
        }
        Ok(())
    })?;
    fn update(
        items: &mut Value,
        anchors: &BTreeMap<String, String>,
        lean_root: Option<&Path>,
        project_root: Option<&Path>,
    ) -> Result<()> {
        if let Some(items) = items.as_array_mut() {
            for item in items {
                if let Some(chapter) = item.get_mut("Chapter") {
                    let path = chapter["path"].as_str().context("chapter has no path")?;
                    let source = chapter["content"]
                        .as_str()
                        .context("chapter has no content")?;
                    let content = render(
                        source,
                        path,
                        anchors,
                        lean_root,
                        project_root,
                        path,
                        "anchor",
                    )
                    .with_context(|| format!("chapter {path}"))?;
                    chapter["content"] = Value::String(content);
                    update(&mut chapter["sub_items"], anchors, lean_root, project_root)?;
                }
            }
        }
        Ok(())
    }
    update(&mut book[key], &anchors, lean_root, project_root)
}

//! Review obligations derived from authored links, without additional Markdown metadata.
//!
//! Extraction and ordering are deterministic. Coverage, clarity, and the reasons
//! for retaining a forward reference are judgments retained as review evidence.
use crate::{
    evidence::{Conclusion, ReviewBundle, ReviewRecord},
    inventory::{hash, input_path, Input, Inventory},
    links::{Direction, LinkInventory, LinkOccurrence, LinkTarget, Location, SourceLinks, Target},
};
use anyhow::{ensure, Context, Result};
use serde::{Deserialize, Serialize};
use std::{
    collections::{BTreeMap, BTreeSet},
    fs,
};

pub fn is_subject(subject: &str) -> bool {
    subject.starts_with("links.") && subject.contains('/')
}

pub fn coverage_subject(unit: &str) -> String {
    format!("links.coverage/{unit}")
}
pub fn target_subject(key: &str) -> String {
    format!("links.target/{}", hash(key.as_bytes()))
}
pub fn forward_subject(occurrence: &str) -> String {
    format!("links.forward/{}", hash(occurrence.as_bytes()))
}

#[derive(Clone, Debug, Serialize, Deserialize)]
#[serde(tag = "kind", rename_all = "snake_case", deny_unknown_fields)]
pub enum Manifest {
    Coverage {
        source: SourceLinks,
    },
    Target {
        target: Target,
    },
    Forward {
        source_unit: String,
        source: Location,
        occurrence: LinkOccurrence,
    },
}

impl Manifest {
    fn subject(&self) -> String {
        match self {
            Self::Coverage { source } => coverage_subject(&source.unit_id),
            Self::Target { target } => target_subject(&target.key),
            Self::Forward { occurrence, .. } => forward_subject(&occurrence.id),
        }
    }

    pub fn location(&self) -> &Location {
        match self {
            Self::Coverage { source } => &source.location,
            Self::Target { target } => &target.location,
            Self::Forward { occurrence, .. } => &occurrence.source,
        }
    }
}

/// One generated inventory is reused across an entire evidence check.
pub struct AuditInventory {
    pub links: LinkInventory,
    pub manifests: BTreeMap<String, Manifest>,
}

impl AuditInventory {
    pub fn build(inventory: &Inventory) -> Result<Self> {
        let links = LinkInventory::build(inventory)?;
        let mut manifests = BTreeMap::new();
        for source in links
            .sources
            .values()
            .filter(|source| source.audit_required)
        {
            let coverage = Manifest::Coverage {
                source: source.clone(),
            };
            manifests.insert(coverage.subject(), coverage);
            for occurrence in &source.occurrences {
                if let LinkTarget::Internal { target } = &occurrence.target {
                    let target = Manifest::Target {
                        target: target.clone(),
                    };
                    manifests.insert(target.subject(), target);
                    if matches!(
                        occurrence.direction,
                        Direction::Forward | Direction::Local | Direction::Unordered
                    ) {
                        let forward = Manifest::Forward {
                            source_unit: source.unit_id.clone(),
                            source: source.location.clone(),
                            occurrence: occurrence.clone(),
                        };
                        manifests.insert(forward.subject(), forward);
                    }
                }
            }
        }
        Ok(Self { links, manifests })
    }

    pub fn inputs(&self, inventory: &Inventory, subject: &str) -> Result<Vec<Input>> {
        let manifest = self
            .manifests
            .get(subject)
            .with_context(|| format!("unknown link audit subject {subject}"))?;
        let mut inputs = inventory.common_inputs()?;
        let location = manifest.location();
        inputs.push(Input::new(
            "audit:subject".into(),
            location.path.clone(),
            location.line,
            serde_json::to_string_pretty(manifest)?,
        ));
        // Source positions participate as content. Ordinary correspondence inputs
        // deliberately ignore line numbers, but moving a link changes its order.
        inputs.push(Input::new(
            "audit:reading-order".into(),
            self.links.summary_path.clone(),
            1,
            serde_json::to_string_pretty(&(&self.links.chapters, &self.links.cycles))?,
        ));
        let summary = fs::read_to_string(input_path(&inventory.root, &self.links.summary_path)?)?;
        inputs.push(Input::new(
            "context:link-summary".into(),
            self.links.summary_path.clone(),
            1,
            summary,
        ));
        let mut paths = BTreeSet::new();
        let mut selections = BTreeMap::new();
        let mut add_source = |unit: &str| -> Result<()> {
            let unit = inventory.unit(unit)?;
            paths.insert(unit.source_path.clone());
            let line = inventory.sources[&unit.source_path][..unit.range.start]
                .bytes()
                .filter(|b| *b == b'\n')
                .count()
                + 1;
            selections.insert(
                format!("audit:unit:{}", unit.id),
                Input::new(
                    format!("audit:unit:{}", unit.id),
                    unit.source_path.clone(),
                    line,
                    unit.raw.clone(),
                ),
            );
            Ok(())
        };
        let mut targets = Vec::new();
        match manifest {
            Manifest::Coverage { source } => {
                add_source(&source.unit_id)?;
                // These are author-declared conceptual context, including concepts
                // that a coverage review may find were not linked in the prose.
                for dependency in &inventory.unit(&source.unit_id)?.uses {
                    add_source(dependency)?;
                }
                for occurrence in &source.occurrences {
                    if let LinkTarget::Internal { target } = &occurrence.target {
                        targets.push(target);
                    }
                }
            }
            Manifest::Target { target } => targets.push(target),
            Manifest::Forward {
                source_unit,
                occurrence,
                ..
            } => {
                add_source(source_unit)?;
                if let LinkTarget::Internal { target } = &occurrence.target {
                    targets.push(target);
                }
            }
        }
        for target in targets {
            paths.insert(target.location.path.clone());
            let source = inventory
                .sources
                .get(&target.location.path)
                .context("link target chapter is absent")?;
            let content = source
                .get(target.location.range.clone())
                .context("invalid target range")?
                .to_owned();
            let key = format!("audit:target:{}", hash(target.key.as_bytes()));
            selections.insert(
                key.clone(),
                Input::new(
                    key,
                    target.location.path.clone(),
                    target.location.line,
                    content,
                ),
            );
        }
        inputs.extend(selections.into_values());
        for path in paths {
            inputs.push(Input::new(
                format!("context:link-chapter:{path}"),
                path.clone(),
                1,
                inventory.sources[&path].clone(),
            ));
        }
        inputs.sort_by(|a, b| a.key.cmp(&b.key));
        Ok(inputs)
    }
}

pub fn subjects(inventory: &Inventory) -> Result<BTreeSet<String>> {
    Ok(AuditInventory::build(inventory)?
        .manifests
        .into_keys()
        .collect())
}

pub fn inputs(inventory: &Inventory, subject: &str) -> Result<Vec<Input>> {
    AuditInventory::build(inventory)?.inputs(inventory, subject)
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum LinkRole {
    Conceptual,
    Navigation,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct LinkAssessment {
    pub occurrence: String,
    pub role: LinkRole,
    pub rationale: String,
}

/// Absolute byte offsets in the snapshotted chapter, not a reviewer-supplied quote.
#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct DefinitionSpan {
    pub path: String,
    pub start: usize,
    pub end: usize,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
#[serde(tag = "kind", rename_all = "snake_case", deny_unknown_fields)]
pub enum OrderAssessment {
    Forward {
        necessity: String,
        signposting: String,
        signpost: DefinitionSpan,
        minimal_use: String,
    },
    Backward {
        rationale: String,
    },
    Navigation {
        rationale: String,
    },
}

#[derive(Clone, Debug, Serialize, Deserialize)]
#[serde(tag = "kind", rename_all = "snake_case", deny_unknown_fields)]
pub enum Assessment {
    Coverage {
        prose: String,
        mathematics: String,
        links: Vec<LinkAssessment>,
    },
    Target {
        subject: String,
        definition: DefinitionSpan,
        clarity: String,
        independence: String,
    },
    Forward {
        assessment: OrderAssessment,
    },
}

pub fn manifest(bundle: &ReviewBundle) -> Result<Manifest> {
    let input = bundle
        .inputs
        .iter()
        .find(|input| input.key == "audit:subject")
        .context("link audit bundle lacks its generated subject manifest")?;
    let manifest: Manifest =
        serde_json::from_str(&input.content).context("invalid link audit manifest")?;
    ensure!(
        manifest.subject() == bundle.unit,
        "audit manifest names another subject"
    );
    Ok(manifest)
}

fn nonempty(errors: &mut Vec<String>, name: &str, text: &str) {
    if text.trim().is_empty() {
        errors.push(format!("link audit requires nonempty {name}"));
    }
}

fn span_errors(bundle: &ReviewBundle, span: &DefinitionSpan, enclosing: &Location) -> Vec<String> {
    let mut errors = Vec::new();
    let source = bundle
        .inputs
        .iter()
        .find(|input| input.key == format!("context:link-chapter:{}", enclosing.path));
    if span.path != enclosing.path
        || span.start < enclosing.range.start
        || span.end > enclosing.range.end
        || span.start >= span.end
    {
        errors.push(
            "reviewed span must be nonempty and inside the exact resolved source/target".into(),
        );
    }
    match source.and_then(|source| source.content.get(span.start..span.end)) {
        Some(text) if !text.trim().is_empty() => {}
        _ => errors
            .push("reviewed span must select nonempty UTF-8 text in the chapter snapshot".into()),
    }
    errors
}

/// Validate against the bundle's immutable manifest as well as the general
/// review schema. Current-source comparison remains the evidence engine's job.
pub fn validate_review(bundle: &ReviewBundle, review: &ReviewRecord) -> Vec<String> {
    if !is_subject(&bundle.unit) {
        return if review.audit.is_some() {
            vec!["correspondence review cannot carry a link audit assessment".into()]
        } else {
            Vec::new()
        };
    }
    let manifest = match manifest(bundle) {
        Ok(manifest) => manifest,
        Err(error) => return vec![format!("{error:#}")],
    };
    let Some(assessment) = &review.audit else {
        return vec!["link audit review requires a purpose-specific audit assessment".into()];
    };
    let mut errors = Vec::new();
    match (&manifest, assessment) {
        (
            Manifest::Coverage { source },
            Assessment::Coverage {
                prose,
                mathematics,
                links,
            },
        ) => {
            nonempty(&mut errors, "prose coverage rationale", prose);
            nonempty(&mut errors, "mathematics coverage rationale", mathematics);
            let expected: BTreeSet<_> = source
                .occurrences
                .iter()
                .map(|link| link.id.as_str())
                .collect();
            let actual: BTreeSet<_> = links.iter().map(|link| link.occurrence.as_str()).collect();
            if actual.len() != links.len() {
                errors.push("duplicate link occurrence assessment".into());
            }
            if actual != expected {
                errors
                    .push("coverage must classify exactly every generated link occurrence".into());
            }
            for link in links {
                nonempty(
                    &mut errors,
                    "link classification rationale",
                    &link.rationale,
                );
                if review.conclusion == Conclusion::Corresponds
                    && link.role == LinkRole::Conceptual
                    && source.occurrences.iter().any(|occurrence| {
                        occurrence.id == link.occurrence
                            && !matches!(occurrence.target, LinkTarget::Internal { .. })
                    })
                {
                    errors.push("conceptual links need a local, snapshotted defining target; external and asset links may only be navigation/source citations".into());
                }
            }
        }
        (
            Manifest::Target { target },
            Assessment::Target {
                subject,
                definition,
                clarity,
                independence,
            },
        ) => {
            nonempty(&mut errors, "target subject", subject);
            nonempty(&mut errors, "target clarity rationale", clarity);
            nonempty(&mut errors, "target independence rationale", independence);
            errors.extend(span_errors(bundle, definition, &target.location));
        }
        (Manifest::Forward { .. }, Assessment::Forward { assessment }) => match assessment {
            OrderAssessment::Forward {
                necessity,
                signposting,
                signpost,
                minimal_use,
            } => {
                for (name, value) in [
                    (
                        "necessity (including rearrangement alternatives)",
                        necessity,
                    ),
                    ("explicit forward signposting", signposting),
                    ("minimal reliance", minimal_use),
                ] {
                    nonempty(&mut errors, name, value);
                }
                // The source-unit range is independently derived and hashed in
                // the manifest, rather than trusting mutable retrieval line numbers.
                if let Manifest::Forward { source, .. } = &manifest {
                    errors.extend(span_errors(bundle, signpost, source));
                }
            }
            OrderAssessment::Backward { rationale } | OrderAssessment::Navigation { rationale } => {
                nonempty(&mut errors, "order disposition rationale", rationale)
            }
        },
        _ => {
            errors.push("audit assessment has the wrong purpose for this generated subject".into())
        }
    }
    errors
}

/// Cross-review consistency is checked from current, active positive records.
/// No review output is smuggled into another review's source hash. A later
/// classification or defining-span change therefore causes a new check.
pub fn cross_validate(
    audits: &AuditInventory,
    active: &BTreeMap<String, Vec<ReviewRecord>>,
) -> Vec<(String, String)> {
    let mut errors = Vec::new();
    let positives = |id: &str| -> Vec<&ReviewRecord> {
        active
            .get(id)
            .into_iter()
            .flatten()
            .filter(|review| review.conclusion == Conclusion::Corresponds)
            .collect()
    };
    // Independent positive reviews cannot disagree silently, even when the
    // link is unambiguously backward and needs no forward-reference subject.
    for (id, records) in active {
        match audits.manifests.get(id) {
            Some(Manifest::Coverage { source }) => {
                for occurrence in &source.occurrences {
                    let roles: BTreeSet<_> = records
                        .iter()
                        .filter_map(|review| match &review.audit {
                            Some(Assessment::Coverage { links, .. }) => links
                                .iter()
                                .find(|link| link.occurrence == occurrence.id)
                                .map(|link| match link.role {
                                    LinkRole::Conceptual => 0,
                                    LinkRole::Navigation => 1,
                                }),
                            _ => None,
                        })
                        .collect();
                    if roles.len() > 1 {
                        errors.push((
                            id.clone(),
                            format!("active coverage reviews disagree about {}", occurrence.id),
                        ));
                    }
                }
            }
            Some(Manifest::Target { .. }) => {
                let definitions: Vec<_> = records
                    .iter()
                    .filter_map(|review| match &review.audit {
                        Some(Assessment::Target { definition, .. }) => Some(definition),
                        _ => None,
                    })
                    .collect();
                if definitions.windows(2).any(|pair| pair[0] != pair[1]) {
                    errors.push((
                        id.clone(),
                        "active target reviews disagree about the defining occurrence".into(),
                    ));
                }
            }
            _ => {}
        }
    }
    for (id, records) in active {
        let Some(Manifest::Forward {
            source_unit,
            occurrence,
            ..
        }) = audits.manifests.get(id)
        else {
            continue;
        };
        let LinkTarget::Internal { target } = &occurrence.target else {
            continue;
        };
        let coverage = positives(&coverage_subject(source_unit));
        let targets = positives(&target_subject(&target.key));
        let roles: BTreeSet<_> = coverage
            .iter()
            .filter_map(|review| match &review.audit {
                Some(Assessment::Coverage { links, .. }) => links
                    .iter()
                    .find(|link| link.occurrence == occurrence.id)
                    .map(|link| match link.role {
                        LinkRole::Conceptual => 0,
                        LinkRole::Navigation => 1,
                    }),
                _ => None,
            })
            .collect();
        if coverage.is_empty() || targets.is_empty() {
            continue;
        } // Their missing evidence is separately blocking.
        if roles.len() != 1 {
            errors.push((
                id.clone(),
                "active coverage reviews disagree about this link's conceptual role".into(),
            ));
            continue;
        }
        let role = *roles.first().unwrap();
        let definitions: Vec<_> = targets
            .iter()
            .filter_map(|review| match &review.audit {
                Some(Assessment::Target { definition, .. }) => Some(definition),
                _ => None,
            })
            .collect();
        for review in records
            .iter()
            .filter(|review| review.conclusion == Conclusion::Corresponds)
        {
            let Some(Assessment::Forward { assessment }) = &review.audit else {
                continue;
            };
            let valid = match assessment {
                OrderAssessment::Navigation { .. } => role == 1,
                OrderAssessment::Forward { .. } => {
                    role == 0
                        && !definitions.is_empty()
                        && definitions.iter().all(|definition| {
                            matches!(
                                definition_direction(&audits.links, occurrence, target, definition),
                                Direction::Forward | Direction::Unordered
                            )
                        })
                }
                OrderAssessment::Backward { .. } => {
                    role == 0
                        && !definitions.is_empty()
                        && definitions.iter().all(|definition| {
                            definition_direction(&audits.links, occurrence, target, definition)
                                == Direction::Backward
                        })
                }
            };
            if !valid {
                errors.push((id.clone(), "order disposition disagrees with current coverage or the actual defining occurrence".into()));
            }
        }
    }
    errors
}

fn definition_direction(
    links: &LinkInventory,
    occurrence: &LinkOccurrence,
    target: &Target,
    definition: &DefinitionSpan,
) -> Direction {
    if definition.path == occurrence.source.path {
        if definition.end <= occurrence.source.range.start {
            Direction::Backward
        } else if definition.start >= occurrence.source.range.end {
            Direction::Forward
        } else {
            Direction::Local
        }
    } else {
        let source = links
            .chapters
            .iter()
            .find(|chapter| chapter.path == occurrence.source.path)
            .map(|chapter| chapter.order);
        match (target.chapter_order, source) {
            (Some(target), Some(source)) if target < source => Direction::Backward,
            (Some(target), Some(source)) if target > source => Direction::Forward,
            _ => Direction::Unordered,
        }
    }
}

//! Deterministic inventory of authored links and their reading order.
//!
//! This module does not guess which words denote concepts. Reviewers classify
//! the extracted links and inspect unlinked prose/math for omissions. A local
//! link only identifies its unit; it does not establish that the linked subject
//! has already been introduced within that unit.
use crate::{
    inventory::{self, Input, Inventory},
    units::UnitKind,
};
use anyhow::{bail, ensure, Context, Result};
use pulldown_cmark::{BrokenLink, Event, LinkType, Options, Parser, Tag, TagEnd};
use serde::{Deserialize, Serialize};
use std::{
    collections::{BTreeMap, BTreeSet},
    ops::Range,
    path::Path,
};

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct Location {
    pub path: String,
    pub range: Range<usize>,
    pub line: usize,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct Chapter {
    pub path: String,
    pub order: usize,
    pub summary_location: Location,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum TargetKind {
    Unit,
    Heading,
    LegacyAnchor,
    Chapter,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct Target {
    /// Canonical repository-relative chapter path followed by its actual HTML fragment.
    pub key: String,
    /// The reviewable definition scope, rather than just its heading or marker.
    pub location: Location,
    /// Exact authored construct corresponding to the rendered link landing point.
    pub anchor_location: Location,
    pub kind: TargetKind,
    pub unit_id: Option<String>,
    pub chapter_order: Option<usize>,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(tag = "kind", rename_all = "snake_case")]
pub enum LinkTarget {
    Internal { target: Target },
    External { url: String },
    Asset { path: String },
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Direction {
    Backward,
    Local,
    Forward,
    Unordered,
    External,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum LinkSyntax {
    Markdown,
    AnchorRef,
    MathJax,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct LinkOccurrence {
    /// Stable for an unchanged authored unit: unit ID and occurrence ordinal.
    pub id: String,
    pub source: Location,
    pub destination: String,
    pub label: String,
    pub syntax: LinkSyntax,
    pub target: LinkTarget,
    pub direction: Direction,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct SourceLinks {
    pub unit_id: String,
    pub unit_kind: UnitKind,
    pub audit_required: bool,
    pub location: Location,
    pub occurrences: Vec<LinkOccurrence>,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct LinkInventory {
    pub sources: BTreeMap<String, SourceLinks>,
    pub chapters: Vec<Chapter>,
    pub targets: BTreeMap<String, Target>,
    /// Strongly connected groups in the unclassified unit-link graph. Navigation
    /// links may account for a cycle; evidence must say which edges are conceptual.
    pub cycles: Vec<Vec<String>>,
    pub summary_path: String,
}

/// Namespace for the inventory builder; retained separately from its serializable result.
pub struct Links;
impl Links {
    pub fn build(inventory: &Inventory) -> Result<LinkInventory> {
        LinkInventory::build(inventory)
    }
}

#[derive(Debug)]
struct RawLink {
    range: Range<usize>,
    destination: String,
    label: String,
    syntax: LinkSyntax,
}

fn location(path: &str, source: &str, range: Range<usize>) -> Location {
    Location {
        path: path.to_owned(),
        line: source[..range.start]
            .bytes()
            .filter(|b| *b == b'\n')
            .count()
            + 1,
        range,
    }
}

fn blank(bytes: &mut [u8], range: Range<usize>) {
    for byte in &mut bytes[range] {
        if !matches!(*byte, b'\n' | b'\r') {
            *byte = b' ';
        }
    }
}

/// Remove presentation fences without moving byte offsets. This makes reference
/// definitions and Markdown in directive bodies part of the same source document.
fn flatten(
    source: &str,
    offset: usize,
    bytes: &mut [u8],
    math: &mut Vec<Range<usize>>,
) -> Result<()> {
    for block in crate::directive_blocks(source) {
        let raw = &source[block.range.clone()];
        let start = raw.find('\n').context("directive has no body")? + 1;
        let end = raw
            .trim_end_matches(['\n', '\r'])
            .rfind('\n')
            .context("directive has no closing fence")?
            + 1;
        let directive = block.info.split_whitespace().next().unwrap_or("");
        let mut body_start = start;
        for line in raw[start..end].split_inclusive('\n') {
            if !line.starts_with(':') {
                break;
            }
            body_start += line.len();
        }
        let base = offset + block.range.start;
        if directive == "{heap}" {
            blank(bytes, base..offset + block.range.end);
            continue;
        }
        blank(bytes, base..base + body_start);
        blank(bytes, base + end..offset + block.range.end);
        let body_range = base + body_start..base + end;
        if matches!(directive, "{grammar}" | "{judgment}" | "{rule}") {
            math.push(body_range);
        } else {
            flatten(&raw[body_start..end], base + body_start, bytes, math)?;
        }
    }
    Ok(())
}

fn literal_ranges(source: &str) -> Vec<Range<usize>> {
    Parser::new(source)
        .into_offset_iter()
        .filter_map(|(event, range)| match event {
            Event::Start(Tag::CodeBlock(_) | Tag::HtmlBlock)
            | Event::Code(_)
            | Event::Html(_)
            | Event::InlineHtml(_) => Some(range),
            _ => None,
        })
        .collect()
}

fn inside(ranges: &[Range<usize>], offset: usize) -> bool {
    ranges.iter().any(|r| r.contains(&offset))
}

fn escaped(source: &str, offset: usize) -> bool {
    source[..offset]
        .bytes()
        .rev()
        .take_while(|b| *b == b'\\')
        .count()
        % 2
        == 1
}

fn explicit_math(source: &str, existing: &[Range<usize>]) -> Result<Vec<Range<usize>>> {
    let literals = literal_ranges(source);
    let mut found = Vec::new();
    let mut previous_end = 0;
    for (start, _) in source.match_indices(r"\\") {
        if start < previous_end
            || escaped(source, start)
            || inside(&literals, start)
            || inside(existing, start)
        {
            continue;
        }
        let closing = match source.as_bytes().get(start + 2) {
            Some(b'[') => r"\\]",
            Some(b'(') => r"\\)",
            _ => continue,
        };
        let end = source[start + 3..]
            .find(closing)
            .map(|n| start + 3 + n + closing.len())
            .context("unclosed explicit mathematics")?;
        found.push(start..end);
        previous_end = end;
    }
    Ok(found)
}

fn group(source: &str, start: usize) -> Result<(Range<usize>, usize)> {
    ensure!(
        source.as_bytes().get(start) == Some(&b'{'),
        "expected braced MathJax href argument"
    );
    let mut depth = 1;
    for (offset, ch) in source[start + 1..].char_indices() {
        let index = start + 1 + offset;
        if escaped(source, index) {
            continue;
        }
        if ch == '{' {
            depth += 1;
        }
        if ch == '}' {
            depth -= 1;
            if depth == 0 {
                return Ok((start + 1..index, index + 1));
            }
        }
    }
    bail!("unclosed MathJax href argument")
}

fn math_links(source: &str, region: Range<usize>) -> Result<Vec<RawLink>> {
    let mut found = Vec::new();
    for (relative, _) in source[region.clone()].match_indices(r"\href") {
        let start = region.start + relative;
        if escaped(source, start)
            || source
                .as_bytes()
                .get(start + 5)
                .is_some_and(u8::is_ascii_alphabetic)
        {
            continue;
        }
        let line_start = source[..start].rfind('\n').map_or(region.start, |n| n + 1);
        if source[line_start..start]
            .match_indices('%')
            .any(|(i, _)| !escaped(source, line_start + i))
        {
            continue;
        }
        let argument = start + 5 + source[start + 5..region.end].len()
            - source[start + 5..region.end].trim_start().len();
        let (url, after_url) = group(&source[..region.end], argument)?;
        let second = after_url + source[after_url..region.end].len()
            - source[after_url..region.end].trim_start().len();
        let (label, end) = group(&source[..region.end], second)?;
        ensure!(
            end <= region.end,
            "MathJax href escapes its mathematics block"
        );
        let destination = &source[url];
        ensure!(!destination.contains(['\\', '{', '}']), "computed or escaped MathJax href destinations are unsupported; use a literal URL with percent escapes");
        found.push(RawLink {
            range: start..end,
            destination: destination.to_owned(),
            label: source[label].to_owned(),
            syntax: LinkSyntax::MathJax,
        });
    }
    Ok(found)
}

struct Document {
    markdown: String,
    links: Vec<RawLink>,
}
fn document(source: &str, path: &str) -> Result<Document> {
    let mut bytes = source.as_bytes().to_vec();
    let mut math = Vec::new();
    flatten(source, 0, &mut bytes, &mut math).with_context(|| format!("{path}:1"))?;
    let flat = String::from_utf8(bytes.clone())?;
    math.extend(explicit_math(&flat, &math).with_context(|| format!("{path}:1"))?);
    let mut links = Vec::new();
    for region in math {
        links.extend(
            math_links(source, region.clone()).with_context(|| {
                format!("{path}:{}", location(path, source, region.clone()).line)
            })?,
        );
        blank(&mut bytes, region);
    }
    let markdown = String::from_utf8(bytes)?;
    let mut current_link = None;
    let mut unresolved = Vec::new();
    let mut callback = |broken: BrokenLink<'_>| {
        if matches!(broken.link_type, LinkType::Reference | LinkType::Collapsed) {
            unresolved.push(broken.span);
        }
        None
    };
    for (event, range) in Parser::new_with_broken_link_callback(
        &markdown,
        Options::ENABLE_HEADING_ATTRIBUTES,
        Some(&mut callback),
    )
    .into_offset_iter()
    {
        match event {
            Event::Start(Tag::Link { dest_url, .. }) => {
                current_link = Some(RawLink {
                    range,
                    destination: dest_url.into_string(),
                    label: String::new(),
                    syntax: LinkSyntax::Markdown,
                });
            }
            Event::Text(text) | Event::Code(text) if current_link.is_some() => {
                current_link.as_mut().unwrap().label.push_str(&text);
            }
            Event::End(TagEnd::Link) => {
                if let Some(link) = current_link.take() {
                    links.push(link);
                }
            }
            Event::Html(html) | Event::InlineHtml(html) => {
                // HTML comments are deliberately inert. An actual HTML link must
                // not disappear from coverage merely because it is not Markdown.
                let text = html.trim_start();
                ensure!(
                    text.starts_with("<!--") || !text.to_ascii_lowercase().contains("href"),
                    "{path}:{}: HTML links are not supported by link auditing; use a Markdown link",
                    location(path, source, range).line
                );
            }
            _ => {}
        }
    }
    if let Some(range) = unresolved.first() {
        bail!(
            "{path}:{}: unresolved reference-style link; supply its Markdown link definition",
            location(path, source, range.clone()).line
        );
    }
    for role in crate::roles(&markdown)? {
        if !role.definition && !role.lean {
            links.push(RawLink {
                range: role.range,
                destination: role.id.clone(),
                label: role.id,
                syntax: LinkSyntax::AnchorRef,
            });
        }
    }
    links.sort_by_key(|link| (link.range.start, link.range.end));
    Ok(Document { markdown, links })
}

fn decode_url(part: &str) -> Result<String> {
    let mut decoded = Vec::new();
    let bytes = part.as_bytes();
    let mut index = 0;
    while index < bytes.len() {
        if bytes[index] == b'%' {
            ensure!(index + 2 < bytes.len(), "incomplete URL percent escape");
            let hex = std::str::from_utf8(&bytes[index + 1..index + 3])?;
            decoded.push(u8::from_str_radix(hex, 16).context("invalid URL percent escape")?);
            index += 3;
        } else {
            decoded.push(bytes[index]);
            index += 1;
        }
    }
    let decoded = String::from_utf8(decoded)?;
    ensure!(
        !decoded.contains(['\\', '\0']) && !decoded.chars().any(char::is_control),
        "unsupported URL path or fragment"
    );
    Ok(decoded)
}

fn external(destination: &str) -> Result<bool> {
    if destination.starts_with("//") {
        return Ok(true);
    }
    if let Some((scheme, _)) = destination.split_once(':') {
        if !scheme.contains('/') && !scheme.contains('#') {
            ensure!(
                matches!(
                    scheme.to_ascii_lowercase().as_str(),
                    "http" | "https" | "mailto"
                ),
                "unsupported link URL scheme `{scheme}`"
            );
            return Ok(true);
        }
    }
    Ok(false)
}

fn relative_target(from: &str, destination: &str, markdown_root: &str) -> Result<String> {
    ensure!(
        !destination.starts_with('/'),
        "root-relative links are ambiguous; use a chapter-relative URL"
    );
    let mut parts: Vec<_> = from.split('/').collect();
    parts.pop();
    for part in destination.split('/') {
        match part {
            "" | "." => {}
            ".." => {
                ensure!(
                    parts.len() > markdown_root.split('/').count(),
                    "link escapes the book source root"
                );
                parts.pop();
            }
            _ => parts.push(part),
        }
    }
    let path = parts.join("/");
    ensure!(
        Path::new(&path).starts_with(markdown_root),
        "link escapes the book source root"
    );
    Ok(path)
}

fn chapter_path(from: &str, destination: &str, markdown_root: &str) -> Result<String> {
    let destination = decode_url(destination)?;
    let mut path = relative_target(from, &destination, markdown_root)?;
    if path.ends_with(".html") {
        path.truncate(path.len() - 5);
        path.push_str(".md");
    }
    Ok(path)
}

fn insert_target(targets: &mut BTreeMap<String, Target>, target: Target) -> Result<()> {
    ensure!(
        !targets.contains_key(&target.key),
        "{}:{}: ambiguous duplicate link target `{}`",
        target.location.path,
        target.location.line,
        target.key
    );
    targets.insert(target.key.clone(), target);
    Ok(())
}

fn slug(text: &str) -> String {
    // Match mdbook-html 0.5.4, utils::id_from_content.
    text.trim()
        .to_lowercase()
        .chars()
        .filter_map(|c| {
            if c.is_alphanumeric() || c == '_' || c == '-' {
                Some(c)
            } else if c.is_whitespace() {
                Some('-')
            } else {
                None
            }
        })
        .collect()
}

impl LinkInventory {
    pub fn build(inventory: &Inventory) -> Result<Self> {
        let markdown_root = inventory::relative_path(
            &inventory.root,
            &inventory
                .source_configuration
                .markdown_root(&inventory.root)?,
        )?;
        let summary_path = format!("{markdown_root}/SUMMARY.md");
        let summary = inventory
            .sources
            .get(&summary_path)
            .context("link order requires the configured book's SUMMARY.md")?;
        let mut chapters = Vec::new();
        let mut chapter_orders = BTreeMap::new();
        for (event, range) in Parser::new(summary).into_offset_iter() {
            if let Event::Start(Tag::Link { dest_url, .. }) = event {
                ensure!(
                    !external(&dest_url)?,
                    "{summary_path}:{}: external SUMMARY entries have no source order",
                    location(&summary_path, summary, range.clone()).line
                );
                ensure!(
                    !dest_url.contains(['#', '?']),
                    "{summary_path}: SUMMARY chapters cannot contain fragments or queries"
                );
                let path = chapter_path(&summary_path, &dest_url, &markdown_root)?;
                ensure!(
                    inventory.sources.contains_key(&path),
                    "{summary_path}: SUMMARY references missing chapter `{path}`"
                );
                ensure!(
                    !chapter_orders.contains_key(&path),
                    "{summary_path}: duplicate chapter `{path}` makes reading order ambiguous"
                );
                let order = chapters.len();
                chapter_orders.insert(path.clone(), order);
                chapters.push(Chapter {
                    path,
                    order,
                    summary_location: location(&summary_path, summary, range),
                });
            }
        }
        let mut targets = BTreeMap::new();
        let mut global_anchors = BTreeMap::new();
        let mut documents = BTreeMap::new();
        for (path, source) in &inventory.sources {
            let doc = document(source, path)?;
            let chapter_order = chapter_orders.get(path).copied();
            insert_target(
                &mut targets,
                Target {
                    key: path.clone(),
                    location: location(path, source, 0..source.len()),
                    anchor_location: location(path, source, 0..0),
                    kind: TargetKind::Chapter,
                    unit_id: None,
                    chapter_order,
                },
            )?;
            for unit in inventory
                .units
                .values()
                .filter(|unit| &unit.source_path == path)
            {
                let key = format!("{path}#claim-{}", unit.id);
                ensure!(
                    global_anchors
                        .insert(unit.id.clone(), key.clone())
                        .is_none(),
                    "{path}:{}: duplicate anchor `{}`",
                    location(path, source, unit.range.clone()).line,
                    unit.id
                );
                // The generated anchor is on the unit header, not at the actual
                // defining sentence. Target review must inspect the complete unit.
                insert_target(
                    &mut targets,
                    Target {
                        key,
                        location: location(path, source, unit.range.clone()),
                        anchor_location: location(
                            path,
                            source,
                            unit.range.start
                                ..unit.range.start
                                    + unit.raw.find('\n').map_or(unit.raw.len(), |end| end + 1),
                        ),
                        kind: TargetKind::Unit,
                        unit_id: Some(unit.id.clone()),
                        chapter_order,
                    },
                )?;
            }
            for role in crate::roles(&doc.markdown)? {
                if role.definition {
                    let key = format!("{path}#claim-{}", role.id);
                    ensure!(
                        global_anchors
                            .insert(role.id.clone(), key.clone())
                            .is_none(),
                        "{path}:{}: duplicate anchor `{}`",
                        location(path, source, role.range.clone()).line,
                        role.id
                    );
                    let unit_id = inventory
                        .units
                        .values()
                        .find(|unit| {
                            unit.source_path == *path && unit.range.contains(&role.range.start)
                        })
                        .map(|unit| unit.id.clone());
                    insert_target(
                        &mut targets,
                        Target {
                            key,
                            location: location(path, source, role.range.clone()),
                            anchor_location: location(path, source, role.range),
                            kind: TargetKind::LegacyAnchor,
                            unit_id,
                            chapter_order,
                        },
                    )?;
                }
            }
            let mut heading = None;
            let mut used = BTreeSet::new();
            let mut headings = Vec::new();
            for (event, range) in Parser::new_ext(&doc.markdown, Options::ENABLE_HEADING_ATTRIBUTES)
                .into_offset_iter()
            {
                match event {
                    Event::Start(Tag::Heading { id, level, .. }) => {
                        heading = Some((range, level, id.map(|id| id.into_string()), String::new()))
                    }
                    Event::Text(text) | Event::Code(text) if heading.is_some() => {
                        heading.as_mut().unwrap().3.push_str(&text)
                    }
                    Event::End(TagEnd::Heading(_)) => {
                        if let Some((range, level, explicit, text)) = heading.take() {
                            let base = explicit.unwrap_or_else(|| slug(&text));
                            let mut id = base.clone();
                            let mut suffix = 0;
                            while !used.insert(id.clone()) {
                                suffix += 1;
                                id = format!("{base}-{suffix}");
                            }
                            headings.push((range, level, id));
                        }
                    }
                    _ => {}
                }
            }
            for (index, (range, level, id)) in headings.iter().enumerate() {
                let unit = inventory
                    .units
                    .values()
                    .find(|unit| unit.source_path == *path && unit.range.contains(&range.start));
                let end = headings[index + 1..]
                    .iter()
                    .find(|(_, next_level, _)| next_level <= level)
                    .map_or(source.len(), |(next, _, _)| next.start)
                    .min(unit.map_or(source.len(), |unit| unit.range.end));
                insert_target(
                    &mut targets,
                    Target {
                        key: format!("{path}#{id}"),
                        location: location(path, source, range.start..end),
                        anchor_location: location(path, source, range.clone()),
                        kind: TargetKind::Heading,
                        unit_id: unit.map(|unit| unit.id.clone()),
                        chapter_order,
                    },
                )?;
            }
            let boundaries: Vec<_> = targets
                .values()
                .filter(|target| {
                    target.location.path == *path && target.kind != TargetKind::Chapter
                })
                .map(|target| target.anchor_location.range.start)
                .collect();
            for target in targets.values_mut().filter(|target| {
                target.location.path == *path && target.kind == TargetKind::LegacyAnchor
            }) {
                let end = if let Some(unit) = target
                    .unit_id
                    .as_ref()
                    .and_then(|id| inventory.units.get(id))
                {
                    unit.range.end
                } else {
                    boundaries
                        .iter()
                        .copied()
                        .filter(|start| *start > target.location.range.start)
                        .min()
                        .unwrap_or(source.len())
                };
                target.location.range.end = end;
            }
            documents.insert(path.clone(), doc);
        }
        let mut sources = BTreeMap::new();
        for unit in inventory.units.values() {
            let source = &inventory.sources[&unit.source_path];
            let mut occurrences = Vec::new();
            for raw in documents[&unit.source_path]
                .links
                .iter()
                .filter(|link| unit.range.contains(&link.range.start))
            {
                let source_location = location(&unit.source_path, source, raw.range.clone());
                let target = resolve(
                    raw,
                    &unit.source_path,
                    &markdown_root,
                    inventory,
                    &targets,
                    &global_anchors,
                )
                .with_context(|| {
                    format!(
                        "{}:{}: link `{}`",
                        source_location.path, source_location.line, raw.destination
                    )
                })?;
                if let LinkTarget::Internal { target } = &target {
                    ensure!(
                        !chapter_orders.contains_key(&unit.source_path) || target.chapter_order.is_some(),
                        "{}:{}: published chapter links to unpublished target `{}`; add the target chapter to SUMMARY.md so its .html page exists",
                        source_location.path, source_location.line, target.key
                    );
                }
                let direction = match &target {
                    LinkTarget::Internal { target }
                        if target.unit_id.as_deref() == Some(&unit.id)
                            || (target.location.path == unit.source_path
                                && target.location.range.contains(&raw.range.start)) =>
                    {
                        Direction::Local
                    }
                    LinkTarget::Internal { target } if target.location.path == unit.source_path => {
                        if target.location.range.start < raw.range.start {
                            Direction::Backward
                        } else {
                            Direction::Forward
                        }
                    }
                    LinkTarget::Internal { target } => {
                        match (chapter_orders.get(&unit.source_path), target.chapter_order) {
                            (Some(from), Some(to)) if *from < to => Direction::Forward,
                            (Some(_), Some(_)) => Direction::Backward,
                            _ => Direction::Unordered,
                        }
                    }
                    _ => Direction::External,
                };
                occurrences.push(LinkOccurrence {
                    id: format!("{}:{}", unit.id, occurrences.len() + 1),
                    source: source_location,
                    destination: raw.destination.clone(),
                    label: raw.label.clone(),
                    syntax: raw.syntax,
                    target,
                    direction,
                });
            }
            sources.insert(
                unit.id.clone(),
                SourceLinks {
                    unit_id: unit.id.clone(),
                    unit_kind: unit.kind,
                    audit_required: true,
                    location: location(&unit.source_path, source, unit.range.clone()),
                    occurrences,
                },
            );
        }
        let cycles = cycles(&sources);
        Ok(Self {
            sources,
            chapters,
            targets,
            cycles,
            summary_path,
        })
    }

    pub fn occurrence(&self, id: &str) -> Option<&LinkOccurrence> {
        self.sources
            .values()
            .flat_map(|source| &source.occurrences)
            .find(|link| link.id == id)
    }

    /// A filesystem-safe, deterministic subject token for target audit records.
    pub fn target_subject(key: &str) -> String {
        inventory::hash(key.as_bytes())
    }

    /// Conservative snapshots: changes to chapter content, anchors, reference
    /// definitions, or SUMMARY ordering invalidate dependent audit evidence.
    pub fn inputs(&self, inventory: &Inventory) -> Vec<Input> {
        inventory
            .sources
            .iter()
            .map(|(path, content)| {
                Input::new(
                    format!("link-source:{path}"),
                    path.clone(),
                    1,
                    content.clone(),
                )
            })
            .collect()
    }
}

fn resolve(
    raw: &RawLink,
    from: &str,
    markdown_root: &str,
    inventory: &Inventory,
    targets: &BTreeMap<String, Target>,
    anchors: &BTreeMap<String, String>,
) -> Result<LinkTarget> {
    if raw.syntax == LinkSyntax::AnchorRef {
        let key = anchors
            .get(&raw.destination)
            .with_context(|| format!("unknown anchor `{}`", raw.destination))?;
        return Ok(LinkTarget::Internal {
            target: targets[key].clone(),
        });
    }
    if external(&raw.destination)? {
        return Ok(LinkTarget::External {
            url: raw.destination.clone(),
        });
    }
    let (path, fragment) = raw
        .destination
        .split_once('#')
        .map_or((raw.destination.as_str(), None), |(p, f)| (p, Some(f)));
    ensure!(
        !path.contains('?'),
        "query-bearing local links are unsupported; use a direct definition URL"
    );
    ensure!(raw.syntax != LinkSyntax::MathJax || !decode_url(path)?.ends_with(".md"), "MathJax links must use the rendered .html chapter URL; mdBook does not rewrite a raw \\href destination ending in .md");
    let path = if path.is_empty() {
        from.to_owned()
    } else {
        chapter_path(from, path, markdown_root)?
    };
    if !inventory.sources.contains_key(&path) {
        ensure!(
            fragment.is_none() && !path.ends_with(".md"),
            "unknown target chapter `{path}`"
        );
        ensure!(
            inventory::input_path(&inventory.root, &path)?.is_file(),
            "local link target must be a file, not a directory: {path}"
        );
        return Ok(LinkTarget::Asset { path });
    }
    let key = match fragment {
        Some(fragment) if !fragment.is_empty() => format!("{path}#{}", decode_url(fragment)?),
        _ => path,
    };
    let target = targets.get(&key).with_context(|| {
        format!("unknown target `{key}`; the path and anchor must identify the same chapter")
    })?;
    Ok(LinkTarget::Internal {
        target: target.clone(),
    })
}

fn cycles(sources: &BTreeMap<String, SourceLinks>) -> Vec<Vec<String>> {
    let graph: BTreeMap<_, BTreeSet<_>> = sources
        .iter()
        .map(|(id, source)| {
            (
                id.clone(),
                source
                    .occurrences
                    .iter()
                    .filter_map(|link| match &link.target {
                        LinkTarget::Internal { target } => target
                            .unit_id
                            .clone()
                            .filter(|other| other != id && sources.contains_key(other)),
                        _ => None,
                    })
                    .collect(),
            )
        })
        .collect();
    fn reachable(graph: &BTreeMap<String, BTreeSet<String>>, from: &str, to: &str) -> bool {
        let mut pending = vec![from.to_owned()];
        let mut seen = BTreeSet::new();
        while let Some(node) = pending.pop() {
            if node == to {
                return true;
            }
            if seen.insert(node.clone()) {
                pending.extend(graph[&node].iter().cloned());
            }
        }
        false
    }
    let mut remaining: BTreeSet<_> = graph.keys().cloned().collect();
    let mut result = Vec::new();
    while let Some(first) = remaining.pop_first() {
        let members: Vec<_> = remaining
            .iter()
            .filter(|other| reachable(&graph, &first, other) && reachable(&graph, other, &first))
            .cloned()
            .collect();
        if !members.is_empty() {
            let mut group = vec![first];
            for member in members {
                remaining.remove(&member);
                group.push(member);
            }
            result.push(group);
        }
    }
    result
}

//! Source-level LaTeX conventions, including literal examples in Markdown.

use anyhow::{ensure, Result};
use regex::Regex;

/// Require an opening group immediately before each overbar command and a
/// literal space immediately after it. Longer TeX control words are separate commands.
pub fn check_latex(source: &str, path: &str) -> Result<()> {
    let overline = Regex::new(r"\\overline([^A-Za-z]|$)")?;
    for matched in overline.captures_iter(source) {
        let command = matched.get(0).expect("a regex match has a full capture");
        let line = source[..command.start()]
            .bytes()
            .filter(|&byte| byte == b'\n')
            .count()
            + 1;
        ensure!(
            source[..command.start()].ends_with('{') && &matched[1] == " ",
            "{path}:{line}: LaTeX style: use {{\\overline f}}; the command must be immediately preceded by `{{` and immediately followed by a literal space"
        );
    }
    Ok(())
}

use anyhow::{ensure, Result};
use std::io;

fn main() -> Result<()> {
    let args: Vec<_> = std::env::args().skip(1).collect();
    if args.first().is_some_and(|a| a == "supports") {
        std::process::exit(if args.get(1).is_some_and(|a| a == "html") {
            0
        } else {
            1
        });
    }
    ensure!(args.is_empty(), "usage: mdbook-dada [supports html]");
    let (context, mut book): (serde_json::Value, serde_json::Value) =
        serde_json::from_reader(io::stdin())?;
    ensure!(
        context["renderer"] == "html",
        "only the HTML renderer is supported"
    );
    mdbook_dada::process_configured(&context, &mut book)?;
    serde_json::to_writer(io::stdout(), &book)?;
    Ok(())
}

//! Recorded command execution, separate from correspondence decisions.
//!
//! Only `run` executes a process. Reading and checking saved receipts is syntactic.
use crate::{
    evidence::write_immutable,
    inventory::{hash, input_path, relative_path, Input},
};
use anyhow::{bail, ensure, Context, Result};
use serde::{Deserialize, Serialize};
use std::{
    collections::{BTreeMap, BTreeSet},
    fs,
    path::{Path, PathBuf},
    process::Command,
    time::{Instant, SystemTime, UNIX_EPOCH},
};

const CONFIG: &str = "spec-checks.json";
const RECORDS: &str = "evidence/executions";
const SCHEMA: u32 = 1;

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Check {
    pub description: String,
    /// Project-relative directory, or `.` for the project root.
    pub cwd: String,
    pub command: Vec<String>,
    pub version: Vec<String>,
    /// Complete files or directories. Generated directories are not inputs.
    pub inputs: Vec<String>,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Configuration {
    pub schema: u32,
    pub checks: BTreeMap<String, Check>,
}

impl Configuration {
    pub fn load(root: &Path) -> Result<Self> {
        let source = input_path(root, CONFIG)?;
        let config: Self = read_json(&source)?;
        ensure!(
            config.schema == SCHEMA,
            "unsupported mechanical-check schema"
        );
        ensure!(!config.checks.is_empty(), "no mechanical checks configured");
        for (name, check) in &config.checks {
            ensure!(
                !name.is_empty()
                    && name
                        .bytes()
                        .all(|b| b.is_ascii_alphanumeric() || b == b'-' || b == b'_'),
                "invalid check name {name}"
            );
            validate_check(check)?;
            working_directory(root, &check.cwd)?;
        }
        Ok(config)
    }
}

fn validate_check(check: &Check) -> Result<()> {
    ensure!(
        check.cwd == "." || normal_path(&check.cwd),
        "check working directory must stay within project sources"
    );
    ensure!(
        !check.description.trim().is_empty(),
        "check needs a description"
    );
    for argv in [&check.command, &check.version] {
        ensure!(
            !argv.is_empty() && !argv[0].trim().is_empty(),
            "check needs command and version argv"
        );
        ensure!(
            argv.iter().all(|arg| !arg.contains('\0')),
            "command contains a NUL byte"
        );
    }
    ensure!(!check.inputs.is_empty(), "check needs source inputs");
    ensure!(
        check.inputs.iter().all(|path| normal_path(path)),
        "check input roots must be normal source paths"
    );
    Ok(())
}

fn working_directory(root: &Path, relative: &str) -> Result<PathBuf> {
    let path = if relative == "." {
        root.to_owned()
    } else {
        input_path(root, relative)?
    };
    ensure!(path.is_dir(), "check working directory is not a directory");
    Ok(path)
}

fn generated(path: &Path) -> bool {
    path.components().any(|part| {
        [".git", ".lake", "target", "book", "evidence"]
            .iter()
            .any(|name| part.as_os_str() == *name)
    })
}

fn collect(root: &Path, path: &Path, inputs: &mut BTreeMap<String, Input>) -> Result<()> {
    let relative = path
        .strip_prefix(root)
        .context("mechanical input outside project")?;
    if generated(relative) {
        return Ok(());
    }
    let name = relative_path(root, path)?;
    let metadata =
        fs::symlink_metadata(path).with_context(|| format!("reading input {}", path.display()))?;
    ensure!(
        !metadata.file_type().is_symlink(),
        "mechanical source tree contains a symbolic link: {}",
        path.display()
    );
    let (kind, content) = if metadata.is_dir() {
        let mut children = Vec::new();
        for entry in fs::read_dir(path)? {
            let child = entry?.path();
            if generated(child.strip_prefix(root)?) {
                continue;
            }
            children.push(
                child
                    .file_name()
                    .context("input has no name")?
                    .to_str()
                    .context("input filename is not UTF-8")?
                    .to_owned(),
            );
            collect(root, &child, inputs)?;
        }
        children.sort();
        ("directory", serde_json::to_string(&children)?)
    } else {
        ensure!(metadata.is_file(), "mechanical input is not a regular file");
        (
            "file",
            fs::read_to_string(path).with_context(|| format!("reading mechanical input {name}"))?,
        )
    };
    inputs.insert(
        name.clone(),
        Input::new(format!("{kind}:{name}"), name, 1, content),
    );
    Ok(())
}

fn normal_path(path: &str) -> bool {
    !path.is_empty()
        && Path::new(path)
            .components()
            .all(|part| matches!(part, std::path::Component::Normal(_)))
        && !generated(Path::new(path))
}

fn validate_snapshot(inputs: &[Input], check: &Check) -> Result<()> {
    let mut previous: Option<&str> = None;
    let mut by_path = BTreeMap::new();
    for input in inputs {
        ensure!(
            normal_path(&input.path)
                && input.line == 1
                && input.sha256 == hash(input.content.as_bytes()),
            "invalid execution input {}",
            input.key
        );
        ensure!(
            previous.is_none_or(|p| p < input.path.as_str()),
            "execution inputs are duplicated or out of order"
        );
        previous = Some(&input.path);
        by_path.insert(input.path.as_str(), input);
    }
    let mut pending: Vec<String> = check.inputs.clone();
    pending.extend([CONFIG.to_owned(), "mdbook-dada/src".to_owned()]);
    let mut visited = BTreeSet::new();
    while let Some(path) = pending.pop() {
        if !visited.insert(path.clone()) {
            continue;
        }
        let input = by_path
            .get(path.as_str())
            .with_context(|| format!("execution omits required input {path}"))?;
        if input.key == format!("directory:{path}") {
            let children: Vec<String> =
                serde_json::from_str(&input.content).context("parsing directory membership")?;
            ensure!(
                children.windows(2).all(|pair| pair[0] < pair[1]),
                "directory membership is duplicated or out of order"
            );
            for child in children {
                ensure!(
                    normal_path(&child) && Path::new(&child).components().count() == 1,
                    "invalid directory entry"
                );
                pending.push(format!("{path}/{child}"));
            }
        } else {
            ensure!(input.key == format!("file:{path}"), "invalid input kind");
        }
    }
    ensure!(visited.len() == inputs.len(), "unexpected execution input");
    ensure!(
        by_path[CONFIG].key == format!("file:{CONFIG}"),
        "check configuration is not a file"
    );
    ensure!(
        by_path["mdbook-dada/src"].key == "directory:mdbook-dada/src",
        "runner source is not a directory"
    );
    Ok(())
}

/// Capture directory membership and complete UTF-8 source contents, in path order.
/// Versioned profiles and runner sources are always included independently of inputs.
pub fn snapshot(root: &Path, check: &Check) -> Result<Vec<Input>> {
    let mut inputs = BTreeMap::new();
    for relative in check
        .inputs
        .iter()
        .map(String::as_str)
        .chain([CONFIG, "mdbook-dada/src"])
    {
        let path = input_path(root, relative)?;
        ensure!(
            !generated(path.strip_prefix(root)?),
            "generated output cannot be a mechanical input"
        );
        // Inspect the lexical path as well, so a selected symlink is not followed.
        let mut lexical = root.to_owned();
        for component in Path::new(relative).components() {
            lexical.push(component);
            ensure!(
                !fs::symlink_metadata(&lexical)?.file_type().is_symlink(),
                "mechanical input uses a symbolic link"
            );
        }
        collect(root, &path, &mut inputs)?;
    }
    Ok(inputs.into_values().collect())
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Outcome {
    pub exit_code: Option<i32>,
    /// Raw bytes preserve non-UTF-8 diagnostics too.
    pub stdout: Vec<u8>,
    pub stderr: Vec<u8>,
    pub launch_error: Option<String>,
}

impl Outcome {
    fn succeeded(&self) -> bool {
        self.exit_code == Some(0) && self.launch_error.is_none()
    }
}

fn execute(argv: &[String], cwd: &Path) -> Outcome {
    match Command::new(&argv[0])
        .args(&argv[1..])
        .current_dir(cwd)
        .output()
    {
        Ok(output) => Outcome {
            exit_code: output.status.code(),
            stdout: output.stdout,
            stderr: output.stderr,
            launch_error: None,
        },
        Err(error) => Outcome {
            exit_code: None,
            stdout: Vec::new(),
            stderr: Vec::new(),
            launch_error: Some(error.to_string()),
        },
    }
}

#[derive(Clone, Debug, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Execution {
    pub schema: u32,
    pub name: String,
    pub check: Check,
    pub host_os: String,
    pub host_arch: String,
    pub started_unix_ms: u128,
    pub finished_unix_ms: u128,
    pub elapsed_ms: u128,
    pub before: Vec<Input>,
    pub after: Option<Vec<Input>>,
    pub after_error: Option<String>,
    pub version_before: Outcome,
    pub command: Option<Outcome>,
    pub version_after: Outcome,
    pub digest: String,
}

impl Execution {
    fn content_digest(&self) -> Result<String> {
        let mut content = self.clone();
        content.digest.clear();
        Ok(hash(&serde_json::to_vec(&content)?))
    }

    /// A successful receipt also requires stable inputs and tool-version output.
    pub fn succeeded(&self) -> bool {
        self.version_before.succeeded()
            && self.version_after == self.version_before
            && self.command.as_ref().is_some_and(Outcome::succeeded)
            && self.after.as_ref() == Some(&self.before)
            && self.after_error.is_none()
    }

    pub fn validate(&self) -> Result<()> {
        ensure!(
            self.schema == SCHEMA && self.content_digest()? == self.digest,
            "execution digest or schema is invalid"
        );
        validate_check(&self.check)?;
        ensure!(!self.before.is_empty(), "execution has no input snapshots");
        ensure!(
            self.after.is_some() != self.after_error.is_some(),
            "execution needs an after snapshot or an error"
        );
        ensure!(
            self.command.is_some() == self.version_before.succeeded(),
            "execution command/version results are inconsistent"
        );
        for inputs in std::iter::once(&self.before).chain(self.after.iter()) {
            validate_snapshot(inputs, &self.check)?;
        }
        let config_input = self
            .before
            .iter()
            .find(|input| input.path == CONFIG)
            .context("missing check configuration")?;
        let config: Configuration = serde_json::from_str(&config_input.content)?;
        ensure!(
            config.schema == SCHEMA && config.checks.get(&self.name) == Some(&self.check),
            "recorded check differs from its configuration snapshot"
        );
        for outcome in [&self.version_before, &self.version_after]
            .into_iter()
            .chain(self.command.iter())
        {
            if let Some(error) = &outcome.launch_error {
                ensure!(
                    !error.is_empty()
                        && outcome.exit_code.is_none()
                        && outcome.stdout.is_empty()
                        && outcome.stderr.is_empty(),
                    "launch error has process output or exit code"
                );
            }
        }
        Ok(())
    }
}

fn now() -> Result<u128> {
    Ok(SystemTime::now().duration_since(UNIX_EPOCH)?.as_millis())
}

/// Execute only an explicitly selected configured check. Preserve failures as well
/// as successes; endpoint snapshots do not provide filesystem isolation.
pub fn run(root: &Path, name: &str) -> Result<PathBuf> {
    let root = root.canonicalize()?;
    let config = Configuration::load(&root)?;
    let check = config
        .checks
        .get(name)
        .with_context(|| format!("unknown mechanical check {name}"))?
        .clone();
    let cwd = working_directory(&root, &check.cwd)?;
    let before = snapshot(&root, &check)?;
    let started_unix_ms = now()?;
    let timer = Instant::now();
    let version_before = execute(&check.version, &cwd);
    let command = version_before
        .succeeded()
        .then(|| execute(&check.command, &cwd));
    let version_after = execute(&check.version, &cwd);
    let (after, after_error) = match snapshot(&root, &check) {
        Ok(inputs) => (Some(inputs), None),
        Err(error) => (None, Some(format!("{error:#}"))),
    };
    let mut receipt = Execution {
        schema: SCHEMA,
        name: name.into(),
        check,
        host_os: std::env::consts::OS.into(),
        host_arch: std::env::consts::ARCH.into(),
        started_unix_ms,
        finished_unix_ms: now()?,
        elapsed_ms: timer.elapsed().as_millis(),
        before,
        after,
        after_error,
        version_before,
        command,
        version_after,
        digest: String::new(),
    };
    receipt.digest = receipt.content_digest()?;
    receipt.validate()?;
    write_immutable(
        &root,
        &PathBuf::from(RECORDS).join(format!("{}.json", receipt.digest)),
        &receipt,
    )
}

fn read_json<T: for<'de> Deserialize<'de>>(path: &Path) -> Result<T> {
    serde_json::from_slice(&fs::read(path).with_context(|| format!("reading {}", path.display()))?)
        .with_context(|| format!("parsing {}", path.display()))
}

pub fn load(path: &Path) -> Result<Execution> {
    let receipt: Execution = read_json(path)?;
    receipt.validate()?;
    ensure!(
        path.file_stem().and_then(|s| s.to_str()) == Some(receipt.digest.as_str()),
        "execution filename differs from digest"
    );
    Ok(receipt)
}

/// Validate retained receipts without executing any commands, including historical
/// failures and receipts for checks no longer configured.
pub fn records(root: &Path) -> Result<Vec<Execution>> {
    let directory = root.join(RECORDS);
    if !directory.exists() {
        return Ok(Vec::new());
    }
    ensure!(
        directory.canonicalize()?.starts_with(root),
        "execution directory escapes project"
    );
    let mut records = Vec::new();
    for entry in fs::read_dir(directory)? {
        let path = entry?.path();
        ensure!(
            !fs::symlink_metadata(&path)?.file_type().is_symlink(),
            "execution receipt is a symbolic link"
        );
        if path.extension().is_some_and(|s| s == "json") {
            records.push(load(&path)?);
        }
    }
    Ok(records)
}

#[derive(Debug)]
pub struct Status {
    pub name: String,
    pub state: &'static str,
    pub receipt: Option<String>,
}

/// Report the latest receipt per configured check. A later failure or stale run
/// cannot be hidden by an older success. Local receipt timestamps are provenance,
/// not an authenticated clock.
pub fn status(root: &Path) -> Result<Vec<Status>> {
    let records = records(root)?;
    if !root.join(CONFIG).exists() {
        if records.is_empty() {
            return Ok(Vec::new());
        }
        bail!("execution receipts exist without {CONFIG}");
    }
    let config = Configuration::load(root)?;
    config
        .checks
        .into_iter()
        .map(|(name, check)| {
            let latest_time = records
                .iter()
                .filter(|r| r.name == name)
                .map(|r| r.finished_unix_ms)
                .max();
            let latest: Vec<_> = records
                .iter()
                .filter(|r| r.name == name && Some(r.finished_unix_ms) == latest_time)
                .collect();
            let current = snapshot(root, &check)?;
            let state = if latest.is_empty() {
                "not recorded"
            } else if latest
                .iter()
                .any(|r| r.check != check || r.before != current)
            {
                "stale"
            } else if latest.iter().any(|r| !r.succeeded()) {
                "recorded failure"
            } else {
                "recorded pass"
            };
            let responsible = latest
                .iter()
                .filter(|r| match state {
                    "stale" => r.check != check || r.before != current,
                    "recorded failure" => !r.succeeded(),
                    _ => true,
                })
                .min_by_key(|r| &r.digest);
            Ok(Status {
                name,
                state,
                receipt: responsible.map(|r| r.digest.clone()),
            })
        })
        .collect()
}

//! Rectilinear routing on corridors around node rectangles.
use anyhow::{Context, Result};
use std::{cmp::Reverse, collections::BinaryHeap};

type Point = (i64, i64);
pub type Rect = (i64, i64, i64, i64);

fn clear(a: Point, b: Point, boxes: &[Rect]) -> bool {
    !boxes.iter().any(|&(x, y, w, h)| {
        if a.0 == b.0 {
            a.0 > x && a.0 < x + w && a.1.min(b.1) < y + h && a.1.max(b.1) > y
        } else {
            a.1 > y && a.1 < y + h && a.0.min(b.0) < x + w && a.0.max(b.0) > x
        }
    })
}

pub fn route(start: Point, end: Point, boxes: &[Rect]) -> Result<Vec<Point>> {
    let mut xs = vec![start.0, end.0];
    let mut ys = vec![start.1, end.1];
    for &(x, y, w, h) in boxes {
        xs.extend([x - 20, x + w + 20]);
        ys.extend([y - 20, y + h + 20]);
    }
    xs.sort_unstable();
    xs.dedup();
    ys.sort_unstable();
    ys.dedup();
    let nx = xs.len();
    let index = |p: Point| -> Result<usize> {
        Ok(
            ys.binary_search(&p.1).ok().context("missing routing y")? * nx
                + xs.binary_search(&p.0).ok().context("missing routing x")?,
        )
    };
    let point = |i: usize| (xs[i % nx], ys[i / nx]);
    let initial = index(start)? * 2;
    let goal = index(end)?;
    let mut costs = vec![i64::MAX; nx * ys.len() * 2];
    let mut previous = vec![None; costs.len()];
    costs[initial] = 0;
    let mut queue = BinaryHeap::from([Reverse((0, initial))]);
    while let Some(Reverse((cost, state))) = queue.pop() {
        if cost != costs[state] {
            continue;
        }
        let node = state / 2;
        if node == goal {
            let mut path = vec![point(node)];
            let mut current = state;
            while let Some(parent) = previous[current] {
                path.push(point(parent / 2));
                current = parent;
            }
            path.reverse();
            let mut compact: Vec<Point> = Vec::new();
            for p in path {
                while compact.len() >= 2 {
                    let a = compact[compact.len() - 2];
                    let b = compact[compact.len() - 1];
                    if (a.0 == b.0 && b.0 == p.0) || (a.1 == b.1 && b.1 == p.1) {
                        compact.pop();
                    } else {
                        break;
                    }
                }
                compact.push(p);
            }
            return Ok(compact);
        }
        let x = node % nx;
        let y = node / nx;
        let neighbors = [
            (x.checked_sub(1).map(|x| y * nx + x), 0),
            ((x + 1 < nx).then_some(node + 1), 0),
            (y.checked_sub(1).map(|y| y * nx + x), 1),
            ((y + 1 < ys.len()).then_some(node + nx), 1),
        ];
        for (next, direction) in neighbors {
            let Some(next) = next else {
                continue;
            };
            let a = point(node);
            let b = point(next);
            if !clear(a, b, boxes) {
                continue;
            }
            let step =
                (a.0 - b.0).abs() + (a.1 - b.1).abs() + if state % 2 == direction { 0 } else { 25 };
            let next_state = next * 2 + direction;
            if cost + step < costs[next_state] {
                costs[next_state] = cost + step;
                previous[next_state] = Some(state);
                queue.push(Reverse((cost + step, next_state)));
            }
        }
    }
    anyhow::bail!("no obstacle-free diagram route from {start:?} to {end:?}")
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn routes_around_boxes_and_through_column_gaps() {
        let boxes = [(100, 0, 80, 80), (100, 140, 80, 80)];
        for (start, end) in [
            ((0, 40), (240, 40)),
            ((0, 110), (240, 110)),
            ((240, 40), (0, 40)),
            ((200, 40), (200, 180)),
        ] {
            let path = route(start, end, &boxes).unwrap();
            assert_eq!(path.first(), Some(&start));
            assert_eq!(path.last(), Some(&end));
            for pair in path.windows(2) {
                assert!(pair[0].0 == pair[1].0 || pair[0].1 == pair[1].1);
                assert!(clear(pair[0], pair[1], &boxes));
            }
        }
        assert_eq!(
            route((0, 110), (240, 110), &boxes).unwrap(),
            vec![(0, 110), (240, 110)]
        );
    }
}

//! Exact source selections for named, unexpanded Rust items.
//!
//! Citations use `relative/file.rs:module::Type::method`. Inline modules are
//! traversed, but external modules and macros are not expanded. Conditional
//! compilation is not evaluated: ambiguous names are rejected even if a build
//! would select just one of them. The complete file is returned as context for
//! selections such as methods whose meaning depends on their enclosing impl.

use std::path::{Component, Path, PathBuf};

use anyhow::{bail, ensure, Context, Result};
use proc_macro2::Span;
use syn::{spanned::Spanned, ImplItem, Item, TraitItem, Type};

/// A source item and the complete file from which it was selected.
#[derive(Clone, Debug)]
pub struct Selection {
    /// Canonical path, guaranteed to remain within the supplied source root.
    pub path: PathBuf,
    pub source: String,
    /// Original source bytes, including the item's attributes and complete body.
    pub selected: String,
    /// Whether this exact item is a free function carrying the built-in test attribute.
    pub is_test: bool,
}

/// Select exactly one named Rust item, without interpreting or executing it.
pub fn select(root: &Path, target: &str) -> Result<Selection> {
    let (file, name) = target
        .split_once(':')
        .with_context(|| format!("Rust citation `{target}` must be `file.rs:Name`"))?;
    let relative = Path::new(file);
    ensure!(
        !relative.as_os_str().is_empty()
            && relative
                .components()
                .all(|part| matches!(part, Component::Normal(_) | Component::CurDir)),
        "Rust citation path `{file}` must be relative and cannot contain `..`"
    );
    ensure!(
        relative
            .extension()
            .is_some_and(|extension| extension == "rs"),
        "Rust citation `{target}` must name a `.rs` file"
    );
    let parsed_name = syn::parse_str::<syn::Path>(name)
        .with_context(|| format!("invalid Rust item name `{name}` in citation `{target}`"))?;
    ensure!(
        parsed_name.leading_colon.is_none()
            && parsed_name
                .segments
                .iter()
                .all(|part| matches!(part.arguments, syn::PathArguments::None)),
        "Rust citation name `{name}` must be an unparameterized item path"
    );
    let root = root
        .canonicalize()
        .with_context(|| format!("cannot locate Rust source root {}", root.display()))?;
    let path = root
        .join(relative)
        .canonicalize()
        .with_context(|| format!("cannot locate Rust source `{file}`"))?;
    ensure!(
        path.starts_with(&root),
        "Rust citation `{target}` escapes its source root through a symlink"
    );
    let source = std::fs::read_to_string(&path)
        .with_context(|| format!("cannot read Rust source {}", path.display()))?;
    let (selected, is_test) = select_source_item(&source, name)
        .with_context(|| format!("cannot select Rust citation `{target}`"))?;
    Ok(Selection {
        path,
        source,
        selected,
        is_test,
    })
}

#[cfg(test)]
fn select_source(source: &str, name: &str) -> Result<String> {
    Ok(select_source_item(source, name)?.0)
}

fn select_source_item(source: &str, name: &str) -> Result<(String, bool)> {
    let file = syn::parse_file(source).context("invalid Rust source")?;
    let mut selections = Vec::new();
    collect_items(&file.items, "", name, &mut selections);
    let (span, is_test) = match selections.as_slice() {
        [] => bail!("no named Rust item `{name}` exists in this file"),
        [selection] => *selection,
        _ => bail!("multiple Rust items named `{name}` exist in this file"),
    };
    source
        .get(span.byte_range())
        .map(|selected| (selected.to_owned(), is_test))
        .context("Rust item span does not identify valid UTF-8 source bytes")
}

fn qualified(prefix: &str, name: impl std::fmt::Display) -> String {
    if prefix.is_empty() {
        name.to_string()
    } else {
        format!("{prefix}::{name}")
    }
}

fn retain_match(
    name: &str,
    target: &str,
    span: Span,
    is_test: bool,
    selections: &mut Vec<(Span, bool)>,
) {
    if name == target {
        selections.push((span, is_test));
    }
}

fn collect_items(items: &[Item], prefix: &str, target: &str, selections: &mut Vec<(Span, bool)>) {
    for item in items {
        let ident = match item {
            Item::Const(item) => Some(&item.ident),
            Item::Enum(item) => Some(&item.ident),
            Item::Fn(item) => Some(&item.sig.ident),
            Item::Macro(item) => item.ident.as_ref(),
            Item::Mod(item) => Some(&item.ident),
            Item::Static(item) => Some(&item.ident),
            Item::Struct(item) => Some(&item.ident),
            Item::Trait(item) => Some(&item.ident),
            Item::TraitAlias(item) => Some(&item.ident),
            Item::Type(item) => Some(&item.ident),
            Item::Union(item) => Some(&item.ident),
            _ => None,
        };
        if let Some(ident) = ident {
            let is_test = match item {
                Item::Fn(function) => function.attrs.iter().any(
                    |attr| matches!(&attr.meta, syn::Meta::Path(path) if path.is_ident("test")),
                ),
                _ => false,
            };
            retain_match(
                &qualified(prefix, ident),
                target,
                item.span(),
                is_test,
                selections,
            );
        }
        match item {
            Item::Mod(module) => {
                if let Some((_, items)) = &module.content {
                    collect_items(items, &qualified(prefix, &module.ident), target, selections);
                }
            }
            Item::Impl(item) => {
                // A path self-type provides an explicit, stable citation name.
                // Generic parameters are omitted, just as in ordinary Rust paths.
                if let Type::Path(self_type) = item.self_ty.as_ref() {
                    if self_type.qself.is_none() {
                        let name = self_type
                            .path
                            .segments
                            .iter()
                            .map(|part| part.ident.to_string())
                            .collect::<Vec<_>>()
                            .join("::");
                        let prefix = qualified(prefix, name);
                        for member in &item.items {
                            let ident = match member {
                                ImplItem::Const(item) => Some(&item.ident),
                                ImplItem::Fn(item) => Some(&item.sig.ident),
                                ImplItem::Type(item) => Some(&item.ident),
                                _ => None,
                            };
                            if let Some(ident) = ident {
                                retain_match(
                                    &qualified(&prefix, ident),
                                    target,
                                    member.span(),
                                    false,
                                    selections,
                                );
                            }
                        }
                    }
                }
            }
            Item::Trait(item) => {
                let prefix = qualified(prefix, &item.ident);
                for member in &item.items {
                    let ident = match member {
                        TraitItem::Const(item) => Some(&item.ident),
                        TraitItem::Fn(item) => Some(&item.sig.ident),
                        TraitItem::Type(item) => Some(&item.ident),
                        _ => None,
                    };
                    if let Some(ident) = ident {
                        retain_match(
                            &qualified(&prefix, ident),
                            target,
                            member.span(),
                            false,
                            selections,
                        );
                    }
                }
            }
            _ => {}
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::sync::atomic::{AtomicUsize, Ordering};

    struct Fixture(PathBuf);

    impl Fixture {
        fn new() -> Self {
            static NEXT: AtomicUsize = AtomicUsize::new(0);
            let path = std::env::temp_dir().join(format!(
                "dada-rust-source-{}-{}",
                std::process::id(),
                NEXT.fetch_add(1, Ordering::Relaxed)
            ));
            std::fs::create_dir(&path).unwrap();
            std::fs::write(path.join("items.rs"), "pub fn checked() {}\n").unwrap();
            Self(path)
        }
    }

    impl Drop for Fixture {
        fn drop(&mut self) {
            std::fs::remove_dir_all(&self.0).unwrap();
        }
    }

    #[test]
    fn selects_complete_test_with_attributes_and_unicode() {
        let source = "// fn checked() { comment decoy } α\nconst TEXT: &str = \"fn checked() {} β\";\n\n#[test]\n#[ignore = \"γ\"]\nfn checked() {\n    let δ = \"ε\";\n    assert_eq!(δ, \"ε\");\n}\nfn later() {}\n";
        assert_eq!(
            select_source(source, "checked").unwrap(),
            "#[test]\n#[ignore = \"γ\"]\nfn checked() {\n    let δ = \"ε\";\n    assert_eq!(δ, \"ε\");\n}"
        );
    }

    #[test]
    fn selects_module_qualified_functions_methods_and_types() {
        let source = "mod nested {\n    pub struct Store<T>(T);\n    impl<T> Store<T> {\n        /// Read an entry.\n        pub fn read(&self) -> &T { &self.0 }\n    }\n    #[test]\n    fn checked() {}\n}\n";
        assert_eq!(
            select_source(source, "nested::Store").unwrap(),
            "pub struct Store<T>(T);"
        );
        assert_eq!(
            select_source(source, "nested::Store::read").unwrap(),
            "/// Read an entry.\n        pub fn read(&self) -> &T { &self.0 }"
        );
        assert_eq!(
            select_source(source, "nested::checked").unwrap(),
            "#[test]\n    fn checked() {}"
        );
        assert!(select_source(source, "checked").is_err());
        assert!(select_source(source, "nested")
            .unwrap()
            .starts_with("mod nested {"));
    }

    #[test]
    fn rejects_missing_ambiguous_and_generated_items() {
        assert!(select_source("fn found() {}", "missing").is_err());
        assert!(
            select_source("#[cfg(a)] fn same() {} #[cfg(b)] fn same() {}", "same")
                .unwrap_err()
                .to_string()
                .contains("multiple")
        );
        assert!(select_source(
            "struct T; impl T { fn same() {} } impl Trait for T { fn same() {} }",
            "T::same"
        )
        .is_err());
        assert!(select_source("generate! { fn generated() {} }", "generated").is_err());
        assert!(select_source("fn outer() { fn inner() {} }", "inner").is_err());
    }

    #[test]
    fn selects_named_data_and_trait_items_without_reformatting() {
        let source = "pub enum Mode { Unique, Shared }\nconst COUNT: usize = 2;\ntype Count = usize;\ntrait Read { fn read(&self); }\n";
        for (name, expected) in [
            ("Mode", "pub enum Mode { Unique, Shared }"),
            ("COUNT", "const COUNT: usize = 2;"),
            ("Count", "type Count = usize;"),
            ("Read", "trait Read { fn read(&self); }"),
            ("Read::read", "fn read(&self);"),
        ] {
            assert_eq!(select_source(source, name).unwrap(), expected);
        }
        assert!(select_source("fn broken( {", "broken").is_err());
    }

    #[test]
    fn rejects_unsafe_paths_and_non_rust_files() {
        let fixture = Fixture::new();
        for target in [
            "items.rs",
            "items.rs:",
            "items.rs:checked::<u8>",
            "items.rs:::checked",
            "../items.rs:checked",
            "/items.rs:checked",
            "items.txt:checked",
            "absent.rs:checked",
        ] {
            assert!(select(&fixture.0, target).is_err(), "accepted {target}");
        }
        let selected = select(&fixture.0, "items.rs:checked").unwrap();
        assert_eq!(selected.selected, "pub fn checked() {}");
        assert_eq!(selected.source, "pub fn checked() {}\n");
        assert_eq!(
            selected.path,
            fixture.0.join("items.rs").canonicalize().unwrap()
        );
    }

    #[cfg(unix)]
    #[test]
    fn rejects_symlinks_outside_root() {
        let fixture = Fixture::new();
        let other = Fixture::new();
        std::os::unix::fs::symlink(other.0.join("items.rs"), fixture.0.join("escape.rs")).unwrap();
        assert!(select(&fixture.0, "escape.rs:checked")
            .unwrap_err()
            .to_string()
            .contains("escapes"));
    }
}

//! Named authored units, selected from the original Markdown before rendering.
//!
//! Byte ranges and `raw` preserve exactly what a reviewer was asked to compare.
//! The parser checks structure only; a citation does not establish correspondence.
use anyhow::{bail, ensure, Context, Result};
use pulldown_cmark::{CodeBlockKind, Event, Parser, Tag, TagEnd};
use serde::{Deserialize, Serialize};
use std::{collections::BTreeSet, ops::Range};

#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum UnitKind {
    Definition,
    Grammar,
    Judgment,
    Rule,
    Theorem,
    Lemma,
    Example,
    FutureNote,
}

impl UnitKind {
    pub fn parse(directive: &str) -> Option<Self> {
        Some(match directive {
            "{definition}" => Self::Definition,
            "{grammar}" => Self::Grammar,
            "{judgment}" => Self::Judgment,
            "{rule}" => Self::Rule,
            "{theorem}" => Self::Theorem,
            "{lemma}" => Self::Lemma,
            "{example}" => Self::Example,
            "{future-note}" => Self::FutureNote,
            _ => return None,
        })
    }

    pub fn label(self) -> &'static str {
        match self {
            Self::Definition => "Definition",
            Self::Grammar => "Grammar",
            Self::Judgment => "Judgment",
            Self::Rule => "Rule",
            Self::Theorem => "Theorem",
            Self::Lemma => "Lemma",
            Self::Example => "Example",
            Self::FutureNote => "Future note",
        }
    }

    pub fn is_math(self) -> bool {
        matches!(self, Self::Grammar | Self::Judgment | Self::Rule)
    }
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct SpecUnit {
    pub id: String,
    pub kind: UnitKind,
    /// Editorial stage, independent of the semantic kind. A draft may lack a
    /// formalization, but must never count as completed correspondence evidence.
    #[serde(default)]
    pub draft: bool,
    pub source_path: String,
    pub range: Range<usize>,
    pub body: String,
    pub raw: String,
    pub lean: Vec<String>,
    pub rust: Vec<String>,
    pub tests: Vec<String>,
    pub uses: Vec<String>,
}

fn valid_id(id: &str) -> bool {
    id.as_bytes().first().is_some_and(u8::is_ascii_alphanumeric)
        && id
            .bytes()
            .all(|c| c.is_ascii_alphanumeric() || matches!(c, b'.' | b'_' | b'-'))
}

fn parse_block(
    source: &str,
    path: &str,
    range: Range<usize>,
    info: &str,
) -> Result<Option<SpecUnit>> {
    let (directive, argument) = info.split_once(char::is_whitespace).unwrap_or((info, ""));
    let Some(kind) = UnitKind::parse(directive) else {
        return Ok(None);
    };
    // Legacy directives carry path:declaration on their opening line. Keep their
    // interpretation, but never mistake them for reviewed structured units.
    if argument.contains(':') {
        ensure!(
            kind != UnitKind::FutureNote,
            "future notes cannot have formalization citations; use a stable unit ID"
        );
        return Ok(None);
    }
    let id = argument.trim();
    if kind.is_math() && id.is_empty() {
        bail!(
            "{directive} requires a stable unit ID, a :lean: citation, and an authored LaTeX body"
        );
    }
    ensure!(
        valid_id(id),
        "expected one stable unit ID after {directive}"
    );
    let raw = &source[range.clone()];
    let opening_end = raw
        .find('\n')
        .context("unit has no body or closing fence")?
        + 1;
    let closing_start = raw
        .trim_end_matches(['\n', '\r'])
        .rfind('\n')
        .context("unit has no closing fence")?
        + 1;
    let opening = raw[..opening_end].trim_start();
    let marker = opening
        .chars()
        .next()
        .context("unit has no opening fence")?;
    let width = opening.chars().take_while(|c| *c == marker).count();
    let closing = raw[closing_start..].trim();
    ensure!(
        matches!(marker, '`' | '~')
            && closing.chars().all(|c| c == marker)
            && closing.len() >= width,
        "structured unit must have an explicit matching closing fence"
    );
    let contents = &raw[opening_end..closing_start];
    let mut unit = SpecUnit {
        id: id.to_owned(),
        kind,
        draft: false,
        source_path: path.to_owned(),
        range,
        body: String::new(),
        raw: raw.to_owned(),
        lean: vec![],
        rust: vec![],
        tests: vec![],
        uses: vec![],
    };
    let mut seen = BTreeSet::new();
    let mut body_start = 0;
    for line in contents.split_inclusive('\n') {
        let line_text = line.trim_end_matches(['\n', '\r']);
        if !line_text.starts_with(':') {
            break;
        }
        let (option, value) = line_text[1..]
            .split_once(':')
            .context("unit option must have the form :name: value")?;
        ensure!(seen.insert(option), "duplicate :{option}: option");
        let values: Vec<_> = value.split_whitespace().map(str::to_owned).collect();
        ensure!(!values.is_empty(), ":{option}: must not be empty");
        if option == "status" {
            ensure!(
                values == ["draft"],
                ":status: only accepts `draft`; omit it for units ready for correspondence review"
            );
            unit.draft = true;
            body_start += line.len();
            continue;
        }
        let target = match option {
            "lean" => &mut unit.lean,
            "rust" => &mut unit.rust,
            "tests" => &mut unit.tests,
            "uses" => &mut unit.uses,
            _ => bail!("unknown unit option :{option}:"),
        };
        let unique: BTreeSet<_> = values.iter().collect();
        ensure!(
            unique.len() == values.len(),
            "duplicate value in :{option}:"
        );
        *target = values;
        body_start += line.len();
    }
    unit.body = contents[body_start..].trim_matches(['\n', '\r']).to_owned();
    // mdBook expands these even inside fenced code. The packet must contain
    // exactly the authored content, not untracked external substitutions.
    let includes = regex::Regex::new(r"\{\{\s*#(?:include|rustdoc_include|playground)\b")?;
    ensure!(
        !includes.is_match(&unit.raw),
        "mdBook include, rustdoc_include, and playground directives are unsupported inside structured units; write the content directly or cite another unit"
    );
    for event in Parser::new(&unit.body) {
        if let Event::Start(Tag::CodeBlock(CodeBlockKind::Fenced(info))) = event {
            let (directive, argument) = info.split_once(char::is_whitespace).unwrap_or((&info, ""));
            ensure!(
                UnitKind::parse(directive).is_none() || !argument.contains(':'),
                "legacy citation directives cannot nest inside structured units; create a separate unit with :lean: and refer to it with :uses:"
            );
        }
    }
    ensure!(
        !unit.body.trim().is_empty(),
        "unit requires an authored body"
    );
    ensure!(
        !unit.body.starts_with(':'),
        "unit options must immediately follow the opening fence, before the blank line and body"
    );
    if kind == UnitKind::FutureNote {
        ensure!(
            unit.lean.is_empty() && unit.rust.is_empty() && unit.tests.is_empty(),
            "future notes cannot have formalization citations (:lean:, :rust:, or :tests:); use a specification unit for formalized content"
        );
        ensure!(!unit.draft, "future notes cannot have :status: draft; they are exploratory notes, not unfinished specification units");
    }
    ensure!(
        kind == UnitKind::FutureNote || unit.draft || !unit.lean.is_empty() || !unit.rust.is_empty(),
        "unit requires :lean: or :rust: citations; use :status: draft while its formalization is pending"
    );
    ensure!(
        unit.tests.is_empty() || !unit.rust.is_empty(),
        ":tests: requires a :rust: implementation citation"
    );
    ensure!(
        unit.lean.is_empty() || unit.rust.is_empty(),
        "a unit cannot mix :lean: and :rust: citations"
    );
    ensure!(
        !matches!(kind, UnitKind::Theorem | UnitKind::Lemma)
            || !unit.lean.is_empty()
            || (unit.draft && unit.rust.is_empty()),
        "theorem and lemma units require a Lean theorem; Rust tests are not proofs"
    );
    ensure!(
        !matches!(
            kind,
            UnitKind::Judgment
                | UnitKind::Rule
                | UnitKind::Theorem
                | UnitKind::Lemma
                | UnitKind::Example
        ) || unit.lean.is_empty()
            || unit.lean.len() == 1,
        "{} requires exactly one Lean citation",
        kind.label()
    );
    for dependency in &unit.uses {
        ensure!(valid_id(dependency), "invalid dependency ID `{dependency}`");
        ensure!(dependency != id, "unit cannot depend on itself");
    }
    ensure!(
        parse(&unit.body, path)?.is_empty(),
        "named units cannot nest; cite the other unit with :uses: or a link"
    );
    Ok(Some(unit))
}

/// IDs mentioned through anchor-reference roles or local Markdown fragments.
/// Generic heading fragments are returned too; the inventory can distinguish
/// them from unit IDs. Explicit `:uses:` remains independently validated.
pub fn linked_ids(body: &str) -> Result<Vec<String>> {
    links(body, false)
}

/// References that explicitly name a claim, rather than an ordinary heading.
/// These must resolve to units even when no matching ID is in the inventory.
pub fn required_linked_ids(body: &str) -> Result<Vec<String>> {
    links(body, true)
}

fn links(body: &str, required_only: bool) -> Result<Vec<String>> {
    let protected = crate::protect_math(body);
    let mut found = BTreeSet::new();
    for role in crate::roles(&protected)? {
        if !role.definition && !role.lean {
            found.insert(role.id);
        }
    }
    for event in Parser::new(&protected) {
        if let Event::Start(Tag::Link { dest_url, .. }) = event {
            if dest_url.contains(':') || dest_url.starts_with("//") {
                continue;
            }
            if let Some((_, fragment)) = dest_url.split_once('#') {
                if required_only && !fragment.starts_with("claim-") {
                    continue;
                }
                let id = fragment.strip_prefix("claim-").unwrap_or(fragment);
                if valid_id(id) {
                    found.insert(id.to_owned());
                }
            }
        }
    }
    Ok(found.into_iter().collect())
}

/// Parse top-level ID-first units. Legacy citation-first directives are excluded.
pub fn parse(source: &str, path: &str) -> Result<Vec<SpecUnit>> {
    reject_removed_syntax(source, path)?;
    let mut units = Vec::new();
    let mut current = None;
    let mut depth = 0;
    for (event, range) in Parser::new(source).into_offset_iter() {
        match event {
            Event::Start(Tag::CodeBlock(CodeBlockKind::Fenced(info)))
                if depth != 0 && info.split_whitespace().next() == Some("{future-note}") =>
            {
                let line = source[..range.start]
                    .bytes()
                    .filter(|b| *b == b'\n')
                    .count()
                    + 1;
                bail!("{path}:{line}: future notes must be top-level units, not nested in lists or blockquotes");
            }
            Event::Start(Tag::CodeBlock(CodeBlockKind::Fenced(info))) if depth == 0 => {
                current = Some((range.start, info.into_string()));
                depth += 1;
            }
            Event::End(TagEnd::CodeBlock) if current.is_some() => {
                let (start, info) = current.take().expect("matched code block");
                let line = source[..start].bytes().filter(|b| *b == b'\n').count() + 1;
                if let Some(unit) = parse_block(source, path, start..range.end, &info)
                    .with_context(|| format!("{path}:{line}"))?
                {
                    ensure!(
                        !units.iter().any(|other: &SpecUnit| other.id == unit.id),
                        "{path}:{line}: duplicate unit ID `{}`",
                        unit.id
                    );
                    units.push(unit);
                }
                depth -= 1;
            }
            Event::Start(_) => depth += 1,
            Event::End(_) => depth -= 1,
            _ => {}
        }
    }
    Ok(units)
}

/// Retired authoring syntax is an error even outside strict chapters or inside
/// lists and quotations. Ordinary code samples and escaped roles remain literal.
fn reject_removed_syntax(source: &str, path: &str) -> Result<()> {
    crate::roles(&crate::protect_math(source)).with_context(|| path.to_owned())?;
    for block in crate::directive_blocks(source) {
        let directive = block.info.split_whitespace().next().unwrap_or("");
        let line = source[..block.range.start]
            .bytes()
            .filter(|byte| *byte == b'\n')
            .count()
            + 1;
        ensure!(
            !directive.starts_with("{obligation}"),
            "{path}:{line}: {{obligation}} has been removed; use a definition, theorem, lemma, or example with :status: draft when formalization is pending"
        );
        if matches!(
            directive,
            "{definition}" | "{theorem}" | "{lemma}" | "{example}" | "{future-note}"
        ) {
            reject_removed_syntax(&block.body, path)?;
        }
    }
    Ok(())
}

/// Strict chapters contain only headings and whitespace outside named units.
/// Callers opt chapters into this policy explicitly; legacy chapters are not
/// silently treated as covered by evidence for unrelated units.
pub fn validate_coverage(source: &str, path: &str) -> Result<()> {
    let units = parse(source, path)?;
    let mut allowed: Vec<_> = units.iter().map(|unit| unit.range.clone()).collect();
    for (event, range) in Parser::new(source).into_offset_iter() {
        if matches!(event, Event::Start(Tag::Heading { .. })) {
            allowed.push(range);
        }
    }
    if let Some((offset, _)) = source.char_indices().find(|(offset, character)| {
        !character.is_whitespace() && !allowed.iter().any(|range| range.contains(offset))
    }) {
        let line = source[..offset].bytes().filter(|b| *b == b'\n').count() + 1;
        bail!("{path}:{line}: content outside a named unit; put semantic prose, mathematics, and examples inside their unit");
    }
    Ok(())
}

