            hash(&serde_json::to_vec(&(reduced.schema, &reduced.unit, identities)).unwrap());
        assert!(evidence::validate_bundle(&fixture.inventory(), &reduced)
            .unwrap()
            .iter()
            .any(|error| error.starts_with("missing required input")));
    }
}

