#[test]
fn rule_citations_cannot_select_an_indented_siblings_constructor() {
    let files = Sources::new();
    std::fs::write(files.lean().join("Sibling.lean"), "inductive First where\n  | first\n  inductive Second where\n  | second\n#check Second.second\n").unwrap();
    for kind in [UnitKind::Grammar, UnitKind::Judgment, UnitKind::Definition] {
        let error = lean::select(&files.lean(), "Sibling:First", kind).unwrap_err();
        assert!(format!("{error:#}").contains("no other commands"));
    }
    let error = lean::select(&files.lean(), "Sibling:First.second", UnitKind::Rule).unwrap_err();
    assert!(format!("{error:#}").contains("no other commands"));
    assert!(render(
        "```{rule} model.invalid\n:lean: Sibling:First.second\n\nP\n```",
        &files.lean()
    )
    .is_err());
    assert!(render("```{rule} Sibling:First.second\nP\n```", &files.lean()).is_err());
}

#[test]
fn rule_selections_preserve_final_literal_tokens() {
    let files = Sources::new();
    for (ty, term) in [
        ("String", r#""zero""#),
        ("String", "r#\"raw -- /- «text»\"#"),
        ("Char", "'α'"),
        ("Char", "'\\n'"),
        ("Nat", "«some index»"),
    ] {
        let header = format!("inductive Indexed : {ty} → Type where");
        let case = format!("  | zero : Indexed {term}");
        for ending in [
            "\n",
            " -- attached\n",
            "\n  -- next constructor\n  | next : Indexed default\n",
        ] {
            std::fs::write(
                files.lean().join("Indexed.lean"),
                format!("{header}\n{case}{ending}"),
            )
            .unwrap();
            let selected =
                lean::select(&files.lean(), "Indexed:Indexed.zero", UnitKind::Rule).unwrap();
            assert!(
                selected.selected.starts_with(&format!("{header}\n{case}")),
                "{}",
                selected.selected
            );
            assert_eq!(
                selected.selected.contains("-- attached"),
                ending.contains("-- attached")
            );
            assert!(!selected.selected.contains("next constructor"));
            assert!(!selected.selected.contains("| next"));
            let output = render(
                "```{rule} model.literal\n:lean: Indexed:Indexed.zero\n\nP\n```",
                &files.lean(),
            )
            .unwrap();
            assert!(output.contains(&mdbook_dada::escape(term)), "{output}");
        }
    }
}

#[test]
fn future_notes_render_without_formalization_or_draft_status() {
    let files = Sources::new();
    let source = "# Ideas\n\n````{future-note} future.views\n\nA possible **extension**.\n\n```dada\nclass Token {}\n```\n````\n\nSee {anchor-ref}`future.views`.";
    let parsed = units::parse(source, "model.md").unwrap();
    assert_eq!(parsed[0].kind, UnitKind::FutureNote);
    assert!(!parsed[0].draft);
    units::validate_coverage(&source[..source.find("\n\nSee").unwrap()], "model.md").unwrap();
    let output = render(source, &files.lean()).unwrap();
    assert!(output.contains("future note: future.views"));
    assert!(output.contains("href=\"#claim-future.views\""));
    assert!(output.contains("A possible **extension**."));
    assert!(output.contains("class Token {}"));
    assert!(!output.contains("type=\"radio\""));
    assert!(!output.contains("unit-status"));
}

#[test]
fn future_notes_reject_formalizations_and_nested_specifications() {
    let files = Sources::new();
    for option in [
        ":lean: Model:initial",
        ":rust: tool.rs:check",
        ":tests: tool.rs:checks",
        ":status: draft",
    ] {
        let source = format!("```{{future-note}} future.views\n{option}\n\nIdea.\n```");
        let error = format!("{:#}", units::parse(&source, "model.md").unwrap_err());
        assert!(error.contains("model.md:1"), "{error}");
        assert!(error.contains("future notes cannot have"), "{error}");
        assert!(render(&source, &files.lean()).is_err());
    }
    for source in [
        "```{future-note} Model:initial\nIdea.\n```",
        "> ```{future-note} future.views\n> :lean: Model:initial\n> \n> Idea.\n> ```",
        "- ```{future-note} future.views\n  :rust: tool.rs:check\n  \n  Idea.\n  ```",
        "````{future-note} future.views\n\n```{definition} Model:initial\nFormalized.\n```\n````",
        "````{future-note} future.views\n\n```{definition} nested\n:lean: Model:initial\n\nFormalized.\n```\n````",
    ] {
        assert!(units::parse(source, "model.md").is_err(), "{source}");
        assert!(render(source, &files.lean()).is_err(), "{source}");
    }
    assert!(lean::select(&files.lean(), "Model:initial", UnitKind::FutureNote).is_err());
    let literal =
        "````text\n```{future-note} sample\n:lean: NotAReal:Citation\n\nLiteral syntax.\n```\n````";
    assert!(units::parse(literal, "model.md").unwrap().is_empty());
    assert_eq!(render(literal, &files.lean()).unwrap(), literal);
}

/* Local shield styling: no external badge service or network request. */
.spec-shield { display:inline-flex; overflow:hidden; border-radius:3px; vertical-align:middle; font:11px/22px Verdana,sans-serif; color:#fff !important; text-decoration:none !important; box-shadow:inset 0 1px 0 #ffffff33; margin:2px 0; max-width:100%; }
.spec-shield-label { background:linear-gradient(#60666e,#474d55); padding:0 7px; }
.spec-shield-name { background:linear-gradient(#31709a,#245778); padding:0 8px; overflow-wrap:anywhere; }
.spec-shield:hover .spec-shield-name { background:#377fae; }
.spec-shield:focus-visible { outline:3px solid var(--links); outline-offset:3px; }
.heap-figure { margin:1.5em 0; padding:1em; border:1px solid var(--table-border-color); border-radius:8px; overflow-x:auto; }
.heap-diagram { display:block; width:100%; min-width:0; max-height:none; color:var(--fg); }
.heap-diagram rect { fill:var(--bg); stroke:var(--fg); stroke-width:1.5; }
.heap-variables rect { fill:var(--quote-bg); }
.heap-diagram text { fill:currentColor; font:14px system-ui,sans-serif; }
.heap-diagram .heap-title { font-weight:600; }
.heap-edge path { fill:none; stroke:currentColor; stroke-width:1.8; }
.heap-edge text { font:12px system-ui,sans-serif; paint-order:stroke; stroke:var(--bg); stroke-width:4px; stroke-linejoin:round; }
.heap-edge.owned { color:var(--fg); }
.heap-edge.showned { color:var(--links); }
.heap-edge.leased path { stroke-dasharray:8 4; }
.heap-edge.shlease path { stroke-dasharray:3 3; }
.heap-edge .heap-arrow { stroke-dasharray:none; }
.heap-figure details { margin-top:0.7em; }
.heap-figure summary { cursor:pointer; color:var(--links); }

.informational-label, .block-label { display:inline-block; font:600 0.75em/1.5 system-ui,sans-serif; border:1px solid var(--table-border-color); border-radius:3px; padding:0 0.4em; margin-right:0.3em; color:var(--fg); background:var(--quote-bg); vertical-align:baseline; }

.lean-declaration { margin:1em 0; }
.lean-declaration figcaption { font:0.75em monospace; opacity:0.7; margin-bottom:0.25em; }
.lean-declaration pre { margin:0; padding:0.7em; }
.lean-keyword { color:var(--links); font-weight:600; }
.lean-declaration details { font-size:0.8em; margin-top:0.3em; }
.lean-selector { display:flex; align-items:center; flex-wrap:wrap; gap:0.6em 1em; font-size:0.85em; }
.lean-selector .block-heading { display:flex; align-items:center; flex-wrap:wrap; gap:0.5em; min-width:0; max-width:100%; }
.lean-selector .block-heading .spec-shield { margin:0; scroll-margin-top:70px; }
.lean-selector .view-options { display:flex; align-items:center; gap:1em; flex-shrink:0; margin-left:auto; }
.lean-selector label { cursor:pointer; white-space:nowrap; }
.lean-group > .lean-source { display:none; }
.lean-group:has(> .lean-selector input:is([value="lean"], [value="rust"]):checked) > .lean-source { display:block; }
.lean-group:has(> .lean-selector input:is([value="lean"], [value="rust"]):checked) > .lean-grammar,
.lean-group:has(> .lean-selector input:is([value="lean"], [value="rust"]):checked) > .lean-markdown-body { display:none; }
.lean-markdown { border:1px solid var(--table-border-color); border-radius:6px; padding:1em; }
.lean-markdown > .lean-source { margin-top:1em; }
.lean-markdown-body > :last-child { margin-bottom:0; }

/* MathJax owns mathematical typography and alignment. */
.lean-grammar { background:var(--quote-bg); border-radius:4px; padding:0.7em 1em; margin:1em 0; overflow-x:auto; }
.math-display { font-size:1.05em; }
.math-display mjx-container[display="true"] { margin:0.5em 0 !important; }
.lean-source pre { overflow-x:auto; }

.heap-figure .heap-facts { display:none; margin-top:1em; }
.heap-figure .lean-selector { margin-bottom:0.75em; }
.heap-figure:has(input[value="facts"]:checked) .heap-facts { display:block; }
.heap-figure:has(input[value="facts"]:checked) .heap-diagram { display:none; }

